function Initialize-MsiNative {
    if($script:MsiNativeLoaded){return $true}
    $cs=@'
using System;
using System.Text;
using System.Runtime.InteropServices;
public static class MsiNative210 {
 [DllImport("msi.dll", CharSet=CharSet.Unicode)] public static extern int MsiQueryProductStateW(string product);
 [DllImport("msi.dll", CharSet=CharSet.Unicode)] public static extern uint MsiGetProductInfoW(string product,string property,StringBuilder value,ref int len);
 [DllImport("msi.dll", CharSet=CharSet.Unicode)] public static extern uint MsiEnumRelatedProductsW(string upgrade,uint reserved,uint index,StringBuilder product);
 [DllImport("msi.dll", CharSet=CharSet.Unicode)] public static extern uint MsiVerifyPackageW(string packagePath);
 public static string ProductInfo(string product,string property){var b=new StringBuilder(4096);int n=b.Capacity-1;uint r=MsiGetProductInfoW(product,property,b,ref n);return r==0?b.ToString():"";}
}
'@
    try{Add-Type -TypeDefinition $cs -Language CSharp -ErrorAction Stop|Out-Null;$script:MsiNativeLoaded=$true;return $true}catch{return $false}
}

function Get-MsiNativeProduct([string]$ProductCode) {
    if(-not (Initialize-MsiNative)){return [PSCustomObject]@{ProductCode=$ProductCode;Registered=$false;State=-999;Version='';LocalPackage='';LocalPackageValid=$false;InstallLocation='';Publisher='';ProductName='';NativeAPI=$false}}
    try{
        $st=[MsiNative210]::MsiQueryProductStateW($ProductCode)
        $local=[MsiNative210]::ProductInfo($ProductCode,'LocalPackage')
        $localValid=$false
        if($local -and (Test-Path -LiteralPath $local)){
            try{$localValid=([MsiNative210]::MsiVerifyPackageW($local) -eq 0)}catch{}
        }
        return [PSCustomObject]@{
            ProductCode=$ProductCode;Registered=($st -ge 3);State=$st;
            Version=[MsiNative210]::ProductInfo($ProductCode,'VersionString');LocalPackage=$local;LocalPackageValid=$localValid;
            InstallLocation=[MsiNative210]::ProductInfo($ProductCode,'InstallLocation');Publisher=[MsiNative210]::ProductInfo($ProductCode,'Publisher');ProductName=[MsiNative210]::ProductInfo($ProductCode,'InstalledProductName');NativeAPI=$true
        }
    }catch{return [PSCustomObject]@{ProductCode=$ProductCode;Registered=$false;State=-998;Version='';LocalPackage='';LocalPackageValid=$false;InstallLocation='';Publisher='';ProductName='';NativeAPI=$false}}
}

function Get-MsiPackageProperty([string]$MsiPath,[string]$Property) {
    if(-not $MsiPath -or -not (Test-Path -LiteralPath $MsiPath) -or -not $Property){return ''}
    $wi=$null;$db=$null;$view=$null;$rec=$null
    try{
        $wi=New-Object -ComObject WindowsInstaller.Installer
        $db=$wi.GetType().InvokeMember('OpenDatabase','InvokeMethod',$null,$wi,@($MsiPath,0))
        $sql="SELECT ``Value`` FROM ``Property`` WHERE ``Property``='$($Property.Replace("'","''"))'"
        $view=$db.GetType().InvokeMember('OpenView','InvokeMethod',$null,$db,@($sql))
        [void]$view.GetType().InvokeMember('Execute','InvokeMethod',$null,$view,$null)
        $rec=$view.GetType().InvokeMember('Fetch','InvokeMethod',$null,$view,$null)
        if($rec){return [string]$rec.GetType().InvokeMember('StringData','GetProperty',$null,$rec,@(1))}
    }catch{}
    finally{
        foreach($o in @($rec,$view,$db,$wi)){if($o){try{[Runtime.InteropServices.Marshal]::FinalReleaseComObject($o)|Out-Null}catch{}}}
    }
    return ''
}

function Get-MsiRelatedProductsNative([string]$UpgradeCode) {
    $out=@();if(-not $UpgradeCode -or -not (Initialize-MsiNative)){return $out}
    for($i=0;$i -lt 128;$i++){
        $b=New-Object Text.StringBuilder 64
        try{$rc=[MsiNative210]::MsiEnumRelatedProductsW($UpgradeCode,0,[uint32]$i,$b)}catch{break}
        if($rc -eq 259){break}
        if($rc -ne 0){break}
        $code=$b.ToString();if($code){$out += Get-MsiNativeProduct $code}
    }
    return $out
}

function Get-FileTrustIdentity([string]$Path,[string]$SignerRegex='') {
    if(-not $Path -or -not (Test-Path -LiteralPath $Path)){return [PSCustomObject]@{Exists=$false;Path=$Path;Valid=$false;Signature='Missing';Signer='';Thumbprint='';Issuer='';NotAfter='';SHA256='';FileVersion='';ProductVersion='';Company=''}}
    try{
        $fi=Get-Item -LiteralPath $Path -ErrorAction Stop;$sig=Get-AuthenticodeSignature -FilePath $Path -ErrorAction Stop
        $subject='';$thumb='';$issuer='';$notAfter=''
        if($sig.SignerCertificate){$subject=[string]$sig.SignerCertificate.Subject;$thumb=[string]$sig.SignerCertificate.Thumbprint;$issuer=[string]$sig.SignerCertificate.Issuer;$notAfter=$sig.SignerCertificate.NotAfter.ToString('o')}
        $valid=($sig.Status -eq 'Valid')
        if($SignerRegex){$valid=($valid -and $subject -match $SignerRegex)}
        return [PSCustomObject]@{Exists=$true;Path=$Path;Valid=$valid;Signature=[string]$sig.Status;Signer=$subject;Thumbprint=$thumb;Issuer=$issuer;NotAfter=$notAfter;SHA256=(Get-FileHash -Algorithm SHA256 -LiteralPath $Path).Hash;FileVersion=[string]$fi.VersionInfo.FileVersion;ProductVersion=[string]$fi.VersionInfo.ProductVersion;Company=[string]$fi.VersionInfo.CompanyName;Size=[int64]$fi.Length}
    }catch{return [PSCustomObject]@{Exists=$true;Path=$Path;Valid=$false;Signature=$_.Exception.Message;Signer='';Thumbprint='';Issuer='';NotAfter='';SHA256='';FileVersion='';ProductVersion='';Company=''}}
}

function Get-TargetInstallerIdentity([object]$Def) {
    $root=Join-Path $env:ProgramFiles ('ASUS\RLSDownload\'+[string]$Def.Rls)
    if(-not (Test-Path -LiteralPath $root)){return [PSCustomObject]@{Found=$false;Root=$root;Path='';Trust=$null}}
    try{
        foreach($f in @(Get-ChildItem -LiteralPath $root -Recurse -File -Filter ([string]$Def.Exe) -ErrorAction SilentlyContinue|Sort-Object LastWriteTime -Descending)){
            $t=Get-FileTrustIdentity $f.FullName ([string]$Def.SignerRegex)
            if($t.Exists){return [PSCustomObject]@{Found=$true;Root=$root;Path=$f.FullName;Trust=$t}}
        }
    }catch{}
    return [PSCustomObject]@{Found=$false;Root=$root;Path='';Trust=$null}
}

function Get-BurnBundleState([string]$BundleId,[string]$SignerRegex='') {
    if(-not $BundleId){return [PSCustomObject]@{BundleId='';Registered=$false;DisplayName='';DisplayVersion='';CachePath='';Trust=$null}}
    $e=Get-UninstallEntry $BundleId;$path=''
    if($e){
        foreach($n in @('QuietUninstallString','UninstallString')){
            $cmd=[string]$e.$n
            if($cmd -match '^\s*"(?<p>[A-Za-z]:\\[^\"]+\.exe)"'){$path=[string]$matches['p'];break}
            if($cmd -match '^\s*(?<p>[A-Za-z]:\\\S+\.exe)'){$path=[string]$matches['p'];break}
        }
    }
    if(-not $path){
        $cache=Join-Path $env:ProgramData ('Package Cache\'+$BundleId)
        if(Test-Path -LiteralPath $cache){$x=Get-ChildItem -LiteralPath $cache -File -Filter '*.exe' -ErrorAction SilentlyContinue|Sort-Object Length -Descending|Select-Object -First 1;if($x){$path=$x.FullName}}
    }
    $trust=$null;if($path){$trust=Get-FileTrustIdentity $path $SignerRegex}
    return [PSCustomObject]@{BundleId=$BundleId;Registered=[bool]$e;DisplayName=$(if($e){[string]$e.DisplayName}else{''});DisplayVersion=$(if($e){[string]$e.DisplayVersion}else{''});CachePath=$path;Trust=$trust}
}

function Get-RuntimeFileFingerprint([object]$Def,[int]$Max=120) {
    $out=@();$root=[string]$Def.InstallRoot;if(-not $root -or -not (Test-Path -LiteralPath $root)){return $out}
    try{
        $files=@()
        foreach($pat in @($Def.RuntimePatterns)){$files += Get-ChildItem -LiteralPath $root -Recurse -File -Filter ([string]$pat) -ErrorAction SilentlyContinue}
        foreach($f in @($files|Sort-Object FullName -Unique|Select-Object -First $Max)){
            try{$sig=Get-AuthenticodeSignature -FilePath $f.FullName -ErrorAction SilentlyContinue;$signer='';if($sig.SignerCertificate){$signer=[string]$sig.SignerCertificate.Subject};$out += [PSCustomObject]@{Path=$f.FullName;FileVersion=[string]$f.VersionInfo.FileVersion;ProductVersion=[string]$f.VersionInfo.ProductVersion;SHA256=(Get-FileHash -Algorithm SHA256 -LiteralPath $f.FullName).Hash;Signature=$(if($sig){[string]$sig.Status}else{'Unknown'});Signer=$signer}}catch{}
        }
    }catch{}
    return $out
}

function Get-ComponentFingerprint([object]$Def,[switch]$IncludeRuntime,[switch]$Force) {
    $cacheKey=([string]$Def.Key)+'|'+$(if($IncludeRuntime){'deep'}else{'shallow'})
    if(-not $Force -and $script:FingerprintCache.ContainsKey($cacheKey) -and $script:FingerprintCacheAt.ContainsKey($cacheKey)){
        try{if(((Get-Date)-[datetime]$script:FingerprintCacheAt[$cacheKey]).TotalSeconds -le 90){return $script:FingerprintCache[$cacheKey]}}catch{}
    }
    $msi=Get-MsiNativeProduct ([string]$Def.ProductCode)
    $resolvedUpgrade=[string]$Def.UpgradeCode
    $upgradeSource='BuiltInRule'
    if(-not $resolvedUpgrade -and $msi.LocalPackage){
        $resolvedUpgrade=Get-MsiPackageProperty ([string]$msi.LocalPackage) 'UpgradeCode'
        if($resolvedUpgrade){$upgradeSource='InstalledMSIProperty'}
    }
    $related=@();if($resolvedUpgrade){$related=@(Get-MsiRelatedProductsNative $resolvedUpgrade)}
    $target=Get-TargetInstallerIdentity $Def
    $oldBundle=Get-BurnBundleState ([string]$Def.OldBundleId) ([string]$Def.SignerRegex)
    $targetBundle=Get-BurnBundleState ([string]$Def.TargetBundleId) ([string]$Def.SignerRegex)
    $runtime=@();if($IncludeRuntime){$runtime=@(Get-RuntimeFileFingerprint $Def)}
    $identityCore=[PSCustomObject]@{
        Key=$Def.Key;ProfileID=$Def.Profile;ProductCode=$Def.ProductCode;UpgradeCode=$resolvedUpgrade;
        MsiVersion=$msi.Version;MsiPublisher=$msi.Publisher;MsiProductName=$msi.ProductName;
        InstallerPath=$target.Path;InstallerSHA256=$(if($target.Trust){$target.Trust.SHA256}else{''});InstallerSigner=$(if($target.Trust){$target.Trust.Signer}else{''});InstallerThumbprint=$(if($target.Trust){$target.Trust.Thumbprint}else{''});InstallerFileVersion=$(if($target.Trust){$target.Trust.FileVersion}else{''});InstallerProductVersion=$(if($target.Trust){$target.Trust.ProductVersion}else{''});
        OldBundleId=$Def.OldBundleId;TargetBundleId=$Def.TargetBundleId
    }
    $identityHash=Get-SHA256Text ($identityCore|ConvertTo-Json -Compress -Depth 8)
    $fp=[PSCustomObject]@{CapturedAt=(Get-Date).ToString('o');IdentityHash=$identityHash;Key=$Def.Key;Name=$Def.Name;ProfileID=$Def.Profile;ProductCode=$Def.ProductCode;UpgradeCode=$resolvedUpgrade;UpgradeCodeSource=$upgradeSource;DefinitionUpgradeCode=$Def.UpgradeCode;ExpectedCode=$Def.ExpectedCode;VerifiedOld=$Def.VerifiedOld;VerifiedGood=$Def.VerifiedGood;MSI=$msi;RelatedProducts=$related;TargetInstaller=$target;OldBundle=$oldBundle;TargetBundle=$targetBundle;InstallRoot=$Def.InstallRoot;RuntimeFiles=$runtime;RuntimeIncluded=[bool]$IncludeRuntime}
    try{
        $latest=Join-Path $FingerprintRoot ($Def.Key+'_latest.json');$oldHash=''
        if(Test-Path -LiteralPath $latest){try{$oldObj=Get-Content -LiteralPath $latest -Raw|ConvertFrom-Json;$oldHash=[string]$oldObj.IdentityHash}catch{}}
        if($identityHash -and $identityHash -ne $oldHash){
            $history=Join-Path $FingerprintRoot ($Def.Key+'_history.jsonl')
            ([PSCustomObject]@{CapturedAt=$fp.CapturedAt;IdentityHash=$identityHash;Identity=$identityCore}|ConvertTo-Json -Compress -Depth 10)|Add-Content -LiteralPath $history -Encoding UTF8
        }
        [void](Write-JsonAtomic $latest $fp 20)
    }catch{}
    $script:FingerprintCache[$cacheKey]=$fp;$script:FingerprintCacheAt[$cacheKey]=Get-Date
    return $fp
}

