    }
    $manifest=[PSCustomObject]@{
        SchemaVersion=1;EngineVersion=$AppVersion;GeneratedAt=(Get-Date).ToString('o');
        RuleSource='BuiltInVerifiedRules';AutoRepairRequiresExactIdentity=$true;Items=$items
    }
    $path=Join-Path $RulePackRoot 'BuiltIn_ComponentIdentityManifest.json'
    [void](Write-JsonAtomic $path $manifest 12)
    return $manifest
}

function Get-RecoveryEvidence([object]$Def,[object]$Fingerprint) {
    $reasons=@();$ready=$false
    if($Fingerprint.OldBundle -and $Fingerprint.OldBundle.Trust -and $Fingerprint.OldBundle.Trust.Valid){$ready=$true;$reasons += ('可验证旧 Burn 包: '+[string]$Fingerprint.OldBundle.CachePath)}
    if($Def.Key -eq 'ENE'){
        try{
            $rp=Join-Path $env:ProgramData ('Package Cache\'+[string]$Def.OldBundleId)
            if(Test-Path -LiteralPath $rp){$ready=$true;$reasons += ('ENE 旧版本缓存目录: '+$rp)}
        }catch{}
    }
    try{
        $rp=Get-ComputerRestorePoint -ErrorAction SilentlyContinue|Sort-Object CreationTime -Descending|Select-Object -First 1
        if($rp){$reasons += '系统还原点功能可读取（辅助恢复层）'}
    }catch{}
    return [PSCustomObject]@{Ready=$ready;Reasons=$reasons}
}

