function Test-ComponentRepairIdentity([object]$Def,[object]$Fingerprint) {
    $block=@();$warn=@()
    if(-not $Fingerprint.MSI.NativeAPI){$block+='Windows Installer 原生 API 不可用'}
    if(-not $Fingerprint.MSI.Registered){$block+="ProductCode 未由 Windows Installer 注册: $($Def.ProductCode)"}
    if($Fingerprint.MSI.Registered){
        if(-not [string]$Fingerprint.MSI.LocalPackage){$warn+='Windows Installer 未返回 LocalPackage；无法额外验证缓存 MSI 包完整性'}
        elseif(-not $Fingerprint.MSI.LocalPackageValid){$block+="Windows Installer LocalPackage 校验失败或缓存 MSI 不可用：$($Fingerprint.MSI.LocalPackage)"}
        if(-not [string]$Fingerprint.MSI.ProductName){$warn+='MSI 原生 API 未返回 InstalledProductName；继续依靠 ProductCode/版本/签名/Bundle 多因子验证'}
        if([string]$Fingerprint.MSI.Publisher -and [string]$Def.SignerRegex -and ([string]$Fingerprint.MSI.Publisher -notmatch [string]$Def.SignerRegex)){
            $block+="MSI Publisher 与组件身份策略不一致：$($Fingerprint.MSI.Publisher)"
        }
    }
    $wantCurrent=if($Def.Key -eq 'ENE'){$Def.VerifiedGood}else{$Def.VerifiedOld}
    if([string]$Fingerprint.MSI.Version -ne [string]$wantCurrent){$block+="MSI 当前版本不等于已验证修复入口：actual=$($Fingerprint.MSI.Version) expected=$wantCurrent"}
    if($Fingerprint.UpgradeCode){
        $relatedCodes=@($Fingerprint.RelatedProducts|ForEach-Object{$_.ProductCode})
        if($relatedCodes -notcontains [string]$Def.ProductCode){$block+="UpgradeCode 关系验证失败：$($Fingerprint.UpgradeCode) 未枚举到目标 ProductCode"}
        elseif($Fingerprint.UpgradeCodeSource -eq 'InstalledMSIProperty'){$warn+="UpgradeCode 来自已安装 MSI Property 动态解析：$($Fingerprint.UpgradeCode)"}
    }else{$warn+='无法从内置规则或已安装 MSI LocalPackage 解析 UpgradeCode；使用 ProductCode + Profile + 签名 + Bundle 多因子验证'}
    if(-not $Fingerprint.TargetInstaller.Found){$block+="目标安装器未找到：$($Def.Exe)"}
    elseif(-not $Fingerprint.TargetInstaller.Trust.Valid){$block+="目标安装器签名/发布者不符合策略：$($Fingerprint.TargetInstaller.Trust.Signature) / $($Fingerprint.TargetInstaller.Trust.Signer)"}
    else{
        $tv=Normalize-VersionText ([string]$Fingerprint.TargetInstaller.Trust.ProductVersion);if(-not $tv){$tv=Normalize-VersionText ([string]$Fingerprint.TargetInstaller.Trust.FileVersion)}
        if($tv -ne [string]$Def.VerifiedGood){$block+="目标安装器版本不是已验证版本：actual=$tv expected=$($Def.VerifiedGood)"}
    }
    $recovery=Get-RecoveryEvidence $Def $Fingerprint
    if(-not $recovery.Ready){$block+='没有找到可验证旧 Burn/回滚包；中央门禁拒绝进入卸载阶段'}
    if($Def.TargetBundleId -and $Def.Key -eq 'ENE' -and -not $Fingerprint.TargetBundle.Registered){$block+="ENE 当前 Burn Provider 未注册：$($Def.TargetBundleId)"}
    return [PSCustomObject]@{Eligible=($block.Count -eq 0);Blocking=$block;Warnings=$warn;Recovery=$recovery;Fingerprint=$Fingerprint}
}

function Test-RepairPolicy([string]$Group,[object[]]$TargetRows) {
    $block=@();$warn=@();$fps=@();$policy=$RepairPolicies[$Group]
    if(-not $policy){return [PSCustomObject]@{Eligible=$false;Blocking=@("未知修复组 $Group");Warnings=@();Fingerprints=@();Policy=$null}}
    $info=Get-ModuleInfo $Group
    if(-not $info -or -not (Test-Path -LiteralPath $info.Module)){$block+='内置修复模块不存在'}
    else{
        try{$actual=(Get-FileHash -Algorithm SHA256 -LiteralPath $info.Module).Hash.ToLowerInvariant();$expected=[string]$ExpectedModuleHashes[[string]$policy.ModuleKey];if($actual -ne $expected){$block+='内置修复模块哈希与策略不一致'}}catch{$block+='无法校验内置修复模块 SHA256'}
    }
    foreach($r in @($TargetRows)){
        if($policy.AllowedKeys -notcontains [string]$r.Key){$block+="计划包含策略外组件：$($r.Key)";continue}
        $d=Get-DefinitionByKey ([string]$r.Key);if(-not $d){$block+="缺少组件定义：$($r.Key)";continue}
        if([string]$r.ErrorCode -notmatch [regex]::Escape([string]$d.ExpectedCode)){$block+="$($r.Key) 当前错误码不等于已验证错误码 $($d.ExpectedCode)"}
        $fp=Get-ComponentFingerprint $d -Force;$fps += $fp
        $x=Test-ComponentRepairIdentity $d $fp
        $block += @($x.Blocking);$warn += @($x.Warnings)
    }
    return [PSCustomObject]@{Eligible=($block.Count -eq 0);Blocking=$block;Warnings=$warn;Fingerprints=$fps;Policy=$policy}
}

function Initialize-RestartManagerNative {
    if($script:RestartManagerLoaded){return $true}
    $cs=@'
using System;using System.Text;using System.Runtime.InteropServices;using System.Collections.Generic;using System.Diagnostics;
public static class RestartManager210 {
 const int CCH_RM_SESSION_KEY=32; const int CCH_RM_MAX_APP_NAME=255; const int CCH_RM_MAX_SVC_NAME=63; const int ERROR_MORE_DATA=234;
 [StructLayout(LayoutKind.Sequential)] public struct FILETIME {public uint dwLowDateTime;public uint dwHighDateTime;}
 [StructLayout(LayoutKind.Sequential)] public struct RM_UNIQUE_PROCESS {public int dwProcessId;public FILETIME ProcessStartTime;}
 public enum RM_APP_TYPE {RmUnknownApp=0,RmMainWindow=1,RmOtherWindow=2,RmService=3,RmExplorer=4,RmConsole=5,RmCritical=1000}
 [StructLayout(LayoutKind.Sequential,CharSet=CharSet.Unicode)] public struct RM_PROCESS_INFO {public RM_UNIQUE_PROCESS Process;[MarshalAs(UnmanagedType.ByValTStr,SizeConst=CCH_RM_MAX_APP_NAME+1)]public string strAppName;[MarshalAs(UnmanagedType.ByValTStr,SizeConst=CCH_RM_MAX_SVC_NAME+1)]public string strServiceShortName;public RM_APP_TYPE ApplicationType;public uint AppStatus;public uint TSSessionId;[MarshalAs(UnmanagedType.Bool)]public bool bRestartable;}
 [DllImport("rstrtmgr.dll",CharSet=CharSet.Unicode)] static extern int RmStartSession(out uint handle,int flags,StringBuilder key);
 [DllImport("rstrtmgr.dll",CharSet=CharSet.Unicode)] static extern int RmRegisterResources(uint handle,uint nFiles,string[] files,uint nApps,RM_UNIQUE_PROCESS[] apps,uint nServices,string[] services);
 [DllImport("rstrtmgr.dll")] static extern int RmGetList(uint handle,out uint needed,ref uint count,[In,Out]RM_PROCESS_INFO[] infos,ref uint reasons);
 [DllImport("rstrtmgr.dll")] static extern int RmEndSession(uint handle);
 public class Item {public int Pid;public string AppName;public string ServiceName;public string Type;public bool Restartable;}
 public static Item[] Query(string[] files,string[] services){var list=new List<Item>();uint h=0;var k=new StringBuilder(CCH_RM_SESSION_KEY+1);if(RmStartSession(out h,0,k)!=0)return list.ToArray();try{int r=RmRegisterResources(h,(uint)(files==null?0:files.Length),files,0,null,(uint)(services==null?0:services.Length),services);if(r!=0)return list.ToArray();uint need=0,cnt=0,reason=0;r=RmGetList(h,out need,ref cnt,null,ref reason);if(r==ERROR_MORE_DATA&&need>0){var a=new RM_PROCESS_INFO[need];cnt=need;r=RmGetList(h,out need,ref cnt,a,ref reason);if(r==0){for(int i=0;i<cnt;i++){list.Add(new Item{Pid=a[i].Process.dwProcessId,AppName=a[i].strAppName,ServiceName=a[i].strServiceShortName,Type=a[i].ApplicationType.ToString(),Restartable=a[i].bRestartable});}}}return list.ToArray();}finally{RmEndSession(h);}}
}
'@
    try{Add-Type -TypeDefinition $cs -Language CSharp -ErrorAction Stop|Out-Null;$script:RestartManagerLoaded=$true;return $true}catch{return $false}
}

function Get-RepairResourceFiles([string]$Group) {
    $files=@();foreach($d in @($Known|Where-Object{$_.Group -eq $Group})){
        if($d.InstallRoot -and (Test-Path -LiteralPath $d.InstallRoot)){
            foreach($pat in @($d.RuntimePatterns)){$files += Get-ChildItem -LiteralPath $d.InstallRoot -Recurse -File -Filter ([string]$pat) -ErrorAction SilentlyContinue|Select-Object -First 20|ForEach-Object{$_.FullName}}
        }
    }
    return @($files|Sort-Object -Unique|Select-Object -First 80)
}

function Get-RestartManagerLocks([string]$Group) {
    if(-not $Group -or -not (Initialize-RestartManagerNative)){return @()}
    $files=@(Get-RepairResourceFiles $Group);if($files.Count -eq 0){return @()}
    try{return @([RestartManager210]::Query([string[]]$files,[string[]]@('ArmouryCrateService','ROG Live Service','LightingService')))}catch{return @()}
}

function Get-InstallerBusyState {
    $all=@();$blocking=@()
    try{if(Test-Path 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Installer\InProgress'){$x=[PSCustomObject]@{Kind='Registry';PID='';StartTime='';CommandLine='Installer\InProgress';Blocking=$true;Reason='Windows Installer InProgress registry key exists'};$all += $x;$blocking += $x}}catch{}
    $seen=@{}
    try{foreach($p in @(Get-CimInstance Win32_Process -Filter "Name='msiexec.exe'" -ErrorAction SilentlyContinue)){$pid=[int]$p.ProcessId;if($seen.ContainsKey($pid)){continue};$seen[$pid]=$true;$cmd=[string]$p.CommandLine;$start='';try{$start=([datetime]$p.CreationDate).ToString('yyyy-MM-dd HH:mm:ss')}catch{};$serviceHost=($cmd -match '(?i)(^|\s)/V(\s|$)');$active=($cmd -match '(?i)(^|\s)/(i|x|package|update|a|j|f|uninstall)(\s|$)|\.msi(\s|$)|\{[0-9A-F-]{36}\}');$isBlock=($active -and -not $serviceHost);$reason=if($isBlock){'active install/repair/uninstall command'}elseif($serviceHost){'Windows Installer service host /V; not an active transaction by itself'}else{'msiexec present; command line does not prove active transaction'};$o=[PSCustomObject]@{Kind='Process';PID=$pid;StartTime=$start;CommandLine=$cmd;Blocking=[bool]$isBlock;Reason=$reason};$all += $o;if($isBlock){$blocking += $o}}}catch{}
    return [PSCustomObject]@{All=@($all);Blocking=@($blocking);Busy=($blocking.Count -gt 0)}
}

function Get-InstallerBusyEvidence {
    $state=Get-InstallerBusyState;$items=@();foreach($x in @($state.Blocking)){if($x.Kind -eq 'Registry'){$items += [string]$x.Reason}else{$cmd=[string]$x.CommandLine;if($cmd.Length -gt 260){$cmd=$cmd.Substring(0,260)+'...'};$items += ("msiexec PID={0} start={1} cmd={2}" -f $x.PID,$x.StartTime,$cmd)}};return $items
}

function Get-ServiceEvidence {
    $out=@();foreach($n in @('ArmouryCrateService','ROG Live Service','LightingService')){try{$s=Get-Service -Name $n -ErrorAction Stop;$out += [PSCustomObject]@{Name=$n;Exists=$true;Status=[string]$s.Status;StartType=[string]$s.StartType}}catch{$out += [PSCustomObject]@{Name=$n;Exists=$false;Status='Missing';StartType=''}}};return $out
}

function Export-RegSafe([string]$Key,[string]$Path) {
    try{& reg.exe export $Key $Path /y | Out-Null;return ($LASTEXITCODE -eq 0 -and (Test-Path -LiteralPath $Path))}catch{return $false}
}

function Get-DirectorySizeSafe([string]$Path) {
    try{return [int64]((Get-ChildItem -LiteralPath $Path -Recurse -File -ErrorAction SilentlyContinue|Measure-Object Length -Sum).Sum)}catch{return [int64]0}
}

function Save-TransactionEvidenceBefore([object]$Tx,[object]$Snap) {
    if(-not $Tx){return}
    $folder=Join-Path $TransactionRoot ([string]$Tx.TransactionId);$ev=Join-Path $folder 'Evidence';$reg=Join-Path $ev 'Registry';$rec=Join-Path $ev 'Recovery';New-Item -ItemType Directory -Force -Path $ev,$reg,$rec|Out-Null
    Write-JsonAtomic (Join-Path $ev 'system_before.json') (Get-WindowsIdentity)|Out-Null
    Write-JsonAtomic (Join-Path $ev 'services_before.json') @(Get-ServiceEvidence)|Out-Null
    Write-JsonAtomic (Join-Path $ev 'snapshot_before.json') ([PSCustomObject]@{CapturedAt=(Get-Date).ToString('o');Rows=Convert-PlanRows $Snap.Rows;ActiveArmoury=@($Snap.ActiveArmoury);ActiveMsi=@($Snap.ActiveMsi);CorrelatedIncidents=@($Snap.CorrelatedIncidents)}) 18|Out-Null
    if($script:RuntimeOnlineInfo){
        Write-JsonAtomic (Join-Path $ev 'microsoft_online_trust_before.json') ([PSCustomObject]@{CheckedAt=$script:RuntimeOnlineCheckedAt.ToString('o');Info=$script:RuntimeOnlineInfo}) 12|Out-Null
    }
    $fps=@();$recoveryItems=@()
    foreach($r in @($Tx.Plan.TargetRows)){
        $d=Get-DefinitionByKey ([string]$r.Key);if(-not $d){continue};$fp=Get-ComponentFingerprint $d -IncludeRuntime -Force;$fps += $fp
        Export-RegSafe ("HKLM\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\"+[string]$d.ProductCode) (Join-Path $reg ($d.Key+'_Product64.reg'))|Out-Null
        Export-RegSafe ("HKLM\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\"+[string]$d.ProductCode) (Join-Path $reg ($d.Key+'_Product32.reg'))|Out-Null
        foreach($bid in @([string]$d.OldBundleId,[string]$d.TargetBundleId)){
            if($bid){Export-RegSafe ("HKLM\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\"+$bid) (Join-Path $reg ($d.Key+'_'+($bid -replace '[{}]','')+'.reg'))|Out-Null}
        }
        if($d.InstallRoot -and (Test-Path -LiteralPath $d.InstallRoot)){
            $size=Get-DirectorySizeSafe ([string]$d.InstallRoot)
            $dest=Join-Path $rec ($d.Key+'_InstallRoot_BEFORE')
            if($size -gt 0 -and $size -le 250MB){try{Copy-Item -LiteralPath ([string]$d.InstallRoot) -Destination $dest -Recurse -Force -ErrorAction Stop;$recoveryItems += [PSCustomObject]@{Kind='InstallRoot';Key=$d.Key;Source=[string]$d.InstallRoot;Backup=$dest;Bytes=$size;Captured=$true}}catch{$recoveryItems += [PSCustomObject]@{Kind='InstallRoot';Key=$d.Key;Source=[string]$d.InstallRoot;Backup=$dest;Bytes=$size;Captured=$false;Error=$_.Exception.Message}}}
            else{$recoveryItems += [PSCustomObject]@{Kind='InstallRoot';Key=$d.Key;Source=[string]$d.InstallRoot;Backup='';Bytes=$size;Captured=$false;Error='目录超过中央 Evidence Bundle 250MB 上限或为空；底层模块仍保留自身备份策略'}}
        }
        $srcHash=Get-SourceHashPath ([string]$d.ProductCode)
        if($srcHash -and (Test-Path -LiteralPath $srcHash)){
            $size=Get-DirectorySizeSafe $srcHash;$dest=Join-Path $rec ($d.Key+'_SourceHash_BEFORE')
            if($size -le 200MB){try{Copy-Item -LiteralPath $srcHash -Destination $dest -Recurse -Force -ErrorAction Stop;$recoveryItems += [PSCustomObject]@{Kind='SourceHash';Key=$d.Key;Source=$srcHash;Backup=$dest;Bytes=$size;Captured=$true}}catch{$recoveryItems += [PSCustomObject]@{Kind='SourceHash';Key=$d.Key;Source=$srcHash;Backup=$dest;Bytes=$size;Captured=$false;Error=$_.Exception.Message}}}
            else{$recoveryItems += [PSCustomObject]@{Kind='SourceHash';Key=$d.Key;Source=$srcHash;Backup='';Bytes=$size;Captured=$false;Error='SourceHash 超过 200MB Evidence Bundle 上限'}}
        }
        if($fp.OldBundle -and $fp.OldBundle.Trust -and $fp.OldBundle.Trust.Valid -and (Test-Path -LiteralPath $fp.OldBundle.CachePath)){
            $dest=Join-Path $rec ($d.Key+'_Rollback_'+[IO.Path]::GetFileName($fp.OldBundle.CachePath))
            try{Copy-Item -LiteralPath $fp.OldBundle.CachePath -Destination $dest -Force -ErrorAction Stop;$recoveryItems += [PSCustomObject]@{Kind='RollbackInstaller';Key=$d.Key;Source=$fp.OldBundle.CachePath;Backup=$dest;SHA256=$fp.OldBundle.Trust.SHA256;Signer=$fp.OldBundle.Trust.Signer;Captured=$true}}catch{$recoveryItems += [PSCustomObject]@{Kind='RollbackInstaller';Key=$d.Key;Source=$fp.OldBundle.CachePath;Backup=$dest;Captured=$false;Error=$_.Exception.Message}}
        }
        if($fp.TargetInstaller -and $fp.TargetInstaller.Trust){
            $recoveryItems += [PSCustomObject]@{Kind='TargetInstallerIdentity';Key=$d.Key;Source=$fp.TargetInstaller.Path;Backup='';SHA256=$fp.TargetInstaller.Trust.SHA256;Signer=$fp.TargetInstaller.Trust.Signer;Thumbprint=$fp.TargetInstaller.Trust.Thumbprint;Version=$(Normalize-VersionText ([string]$fp.TargetInstaller.Trust.ProductVersion));Captured=$true}
        }
    }
    Write-JsonAtomic (Join-Path $ev 'component_fingerprints_before.json') $fps 20|Out-Null
    Write-JsonAtomic (Join-Path $ev 'recovery_manifest.json') $recoveryItems 12|Out-Null
    $locks=@();if($Tx.Group){$locks=@(Get-RestartManagerLocks ([string]$Tx.Group))};Write-JsonAtomic (Join-Path $ev 'restart_manager_before.json') $locks 8|Out-Null
    $Tx|Add-Member -NotePropertyName EvidencePath -NotePropertyValue $ev -Force
    $Tx|Add-Member -NotePropertyName RecoveryManifestPath -NotePropertyValue (Join-Path $ev 'recovery_manifest.json') -Force
    $Tx|Add-Member -NotePropertyName BootTimeBefore -NotePropertyValue (Get-BootTimeText) -Force
    Save-Transaction $Tx
}

function Save-TransactionEvidenceAfter([object]$Tx,[object]$Snap) {
    if(-not $Tx){return};$folder=Join-Path $TransactionRoot ([string]$Tx.TransactionId);$ev=Join-Path $folder 'Evidence';New-Item -ItemType Directory -Force -Path $ev|Out-Null
    Write-JsonAtomic (Join-Path $ev 'system_after.json') (Get-WindowsIdentity)|Out-Null
    Write-JsonAtomic (Join-Path $ev 'services_after.json') @(Get-ServiceEvidence)|Out-Null
    Write-JsonAtomic (Join-Path $ev 'snapshot_after.json') ([PSCustomObject]@{CapturedAt=(Get-Date).ToString('o');Rows=Convert-PlanRows $Snap.Rows;ActiveArmoury=@($Snap.ActiveArmoury);ActiveMsi=@($Snap.ActiveMsi)}) 16|Out-Null
    $fps=@();foreach($r in @($Tx.Plan.TargetRows)){$d=Get-DefinitionByKey ([string]$r.Key);if($d){$fps += Get-ComponentFingerprint $d -IncludeRuntime -Force}}
    Write-JsonAtomic (Join-Path $ev 'component_fingerprints_after.json') $fps 20|Out-Null
    if($script:RuntimeOnlineInfo){Write-JsonAtomic (Join-Path $ev 'microsoft_online_trust_after.json') ([PSCustomObject]@{CheckedAt=$script:RuntimeOnlineCheckedAt.ToString('o');Info=$script:RuntimeOnlineInfo}) 12|Out-Null}
    if($Tx.Type -eq 'RUNTIME'){
        try{Write-JsonAtomic (Join-Path $ev 'runtime_deep_test_after.json') ([PSCustomObject]@{CheckedAt=(Get-Date).ToString('o');Rows=@(Invoke-GameRuntimeDeepTest)}) 10|Out-Null}catch{}
    }
    $bootAfter=Get-BootTimeText
    $Tx|Add-Member -NotePropertyName BootTimeAfter -NotePropertyValue $bootAfter -Force
    $Tx|Add-Member -NotePropertyName RebootObserved -NotePropertyValue ([bool]($Tx.BootTimeBefore -and $bootAfter -and ([string]$Tx.BootTimeBefore -ne [string]$bootAfter))) -Force
    Save-Transaction $Tx
}

function Get-CorrelatedIncidents([object[]]$Armoury,[object[]]$Msi) {
    $out=@()
    foreach($a in @($Armoury)){
        $score=40;$e=@("Armoury $($a.Code)")
        if($a.Profile){$score+=15;$e += "Profile=$($a.Profile)"}
        if($a.CurrentVersion -or $a.TargetVersion){$score+=10;$e += "$($a.CurrentVersion)->$($a.TargetVersion)"}
        $near=@($Msi|Where-Object{[Math]::Abs((($_.ObservedAt)-($a.ObservedAt)).TotalSeconds) -le 120})
        if($near.Count -gt 0){$score+=25;$e += "MSI nearby=$($near.Count)"}
        $tokens=@([string]$a.Component,[string]$a.Package,[string]$a.Installer)|Where-Object{$_ -and $_.Trim().Length -ge 3}|Sort-Object -Unique
        $same=@()
        if($tokens.Count -gt 0 -and $near.Count -gt 0){
            $same=@($near|Where-Object{
                $m=[string]$_.Message;$hit=$false
                foreach($t in $tokens){if($m -match [regex]::Escape($t)){$hit=$true;break}}
                $hit
            })
        }
        if($same.Count -gt 0){$score+=10;$e += 'same component/installer text'}
        if($score -gt 100){$score=100}
        $conf=if($score -ge 75){'HIGH'}elseif($score -ge 55){'MEDIUM'}else{'LOW'}
        $out += [PSCustomObject]@{ObservedAt=$a.ObservedAt;Code=$a.Code;Component=$a.Component;Profile=$a.Profile;Score=$score;Confidence=$conf;Evidence=($e -join '; ');DedupKey=$a.DedupKey}
    }
    return $out
}

function Get-ModuleInternalState([string]$Group) {
    $ptr='';switch($Group){'PV'{$ptr=Join-Path $env:ProgramData 'ASUS4151TargetedFix\CurrentStatePath.txt'}'HOLTEK'{$ptr=Join-Path $env:ProgramData 'ASUSCoreHAL4151Fix\CurrentStatePath.txt'}'ENE'{$ptr=Join-Path $env:ProgramData 'ASUS_ENE_M2_4152_Fix\CurrentStatePath.txt'}}
    if(-not $ptr -or -not (Test-Path -LiteralPath $ptr)){return $null}
    try{$sp=(Get-Content -LiteralPath $ptr -Raw).Trim();if(Test-Path -LiteralPath $sp){$x=Get-Content -LiteralPath $sp -Raw|ConvertFrom-Json;return [PSCustomObject]@{Pointer=$ptr;StatePath=$sp;Phase=[string]$x.Phase;Raw=$x}}}catch{}
    return $null
}

function Restore-ExpectedServicesFromEvidence([object]$Tx) {
    if(-not $Tx -or -not $Tx.EvidencePath){return}
    $p=Join-Path ([string]$Tx.EvidencePath) 'services_before.json';if(-not (Test-Path -LiteralPath $p)){return}
    try{foreach($x in @(Get-Content -LiteralPath $p -Raw|ConvertFrom-Json)){if($x.Exists -and $x.Status -eq 'Running'){try{$s=Get-Service -Name ([string]$x.Name) -ErrorAction Stop;if($s.Status -ne 'Running'){Start-Service -Name ([string]$x.Name) -ErrorAction SilentlyContinue}}catch{}}}}catch{}
}

$ObservationWorkerPath=Join-Path $WorkRoot 'TransactionObservationWorker.ps1'
function Write-ObservationWorker {
    $w=@'
param([string]$ResultPath,[int]$Seconds=60,[bool]$RequireAsusServices=$false)
$ErrorActionPreference='SilentlyContinue'
function MsiCounts {
    $o=@{}
    try{
        foreach($e in @(Get-WinEvent -FilterHashtable @{LogName='Application';ProviderName='MsiInstaller';StartTime=(Get-Date).AddMinutes(-30)} -ErrorAction SilentlyContinue)){
            if($e.Message -match '(?i)(1603|1618|1721|11721)' -and $e.Message -match '(?i)(ASUS|Armoury|ENE|HAL|Aac|Aura|Patriot|Holtek|VGA)'){
                $k=[string]$e.RecordId
                if(-not $o.ContainsKey($k)){$o[$k]=0};$o[$k]++
            }
        }
    }catch{}
    return $o
}
function AsusCounts {
    $o=@{}
    foreach($root in @("$env:ProgramData\ASUS","$env:LOCALAPPDATA\ASUS")){
        if(-not (Test-Path -LiteralPath $root)){continue}
        try{
            foreach($f in @(Get-ChildItem -LiteralPath $root -Recurse -File -ErrorAction SilentlyContinue|Where-Object{$_.Extension -match '^\.(log|txt)$' -and $_.Length -lt 12MB}|Sort-Object LastWriteTime -Descending|Select-Object -First 140)){
                try{
                    foreach($line in @(Get-Content -LiteralPath $f.FullName -Tail 2500 -ErrorAction Stop)){
                        if($line -match '(?i)(UI\s*code\s*[:=]\s*4\d{3}|uicode\s*[:=]\s*4\d{3}|Optional\s+Hal\s+4\d{3}|FailedVersionMismatch)'){
                            $norm=($line -replace '\s+',' ').Trim()
                            $k=$f.FullName+'|'+$norm
                            if(-not $o.ContainsKey($k)){$o[$k]=0};$o[$k]++
                        }
                    }
                }catch{}
            }
        }catch{}
    }
    return $o
}
function NewCount($before,$after){
    $n=0
    foreach($k in @($after.Keys)){
        $b=0;if($before.ContainsKey($k)){$b=[int]$before[$k]}
        $a=[int]$after[$k]
        if($a -gt $b){$n += ($a-$b)}
    }
    return $n
}
$beforeM=MsiCounts;$beforeA=AsusCounts
Start-Sleep -Seconds $Seconds
$afterM=MsiCounts;$afterA=AsusCounts
$newM=NewCount $beforeM $afterM;$newA=NewCount $beforeA $afterA
$svc=@();$svcBad=0
foreach($n in @('ArmouryCrateService','ROG Live Service','LightingService')){
    try{$s=Get-Service -Name $n -ErrorAction Stop;$svc += [pscustomobject]@{Name=$n;Exists=$true;Status=[string]$s.Status};if($RequireAsusServices -and $s.Status -ne 'Running'){$svcBad++}}
    catch{$svc += [pscustomobject]@{Name=$n;Exists=$false;Status='Missing'};if($RequireAsusServices){$svcBad++}}
}
$r=[pscustomobject]@{CheckedAt=(Get-Date).ToString('o');Seconds=$Seconds;RequireAsusServices=$RequireAsusServices;Success=($newM -eq 0 -and $newA -eq 0 -and $svcBad -eq 0);NewMsiCount=$newM;NewArmouryCount=$newA;BadServiceCount=$svcBad;Services=$svc}
$tmp=$ResultPath+'.tmp';$r|ConvertTo-Json -Depth 6|Set-Content -LiteralPath $tmp -Encoding UTF8;Move-Item -LiteralPath $tmp -Destination $ResultPath -Force
'@
    try{$w|Set-Content -LiteralPath $ObservationWorkerPath -Encoding UTF8;return $true}catch{return $false}
}

function Start-TransactionObservation([object]$Tx,[int]$Seconds=60) {
    if(-not $Tx -or -not (Write-ObservationWorker)){return $false}
    Restore-ExpectedServicesFromEvidence $Tx
    $folder=Join-Path $TransactionRoot ([string]$Tx.TransactionId);$result=Join-Path $folder 'observation.json';Remove-Item -LiteralPath $result -Force -ErrorAction SilentlyContinue
    $Tx|Add-Member -NotePropertyName ObservationResultPath -NotePropertyValue $result -Force
    $Tx|Add-Member -NotePropertyName ObservationSeconds -NotePropertyValue $Seconds -Force
    Set-TransactionState $Tx 'Observing' "初步验证通过；开始 ${Seconds}s 修复后观察期"
    $ps=Join-Path $env:WINDIR 'System32\WindowsPowerShell\v1.0\powershell.exe'
    $requireAsus=($Tx.Type -eq 'ASUS')
    $args="-NoProfile -ExecutionPolicy Bypass -WindowStyle Hidden -File `"$ObservationWorkerPath`" -ResultPath `"$result`" -Seconds $Seconds -RequireAsusServices `$$requireAsus"
    try{$script:ObservationWorker=Start-Process -FilePath $ps -ArgumentList $args -PassThru -WindowStyle Hidden;return $true}catch{Set-TransactionState $Tx 'NeedsAttention' ('无法启动观察期 worker: '+$_.Exception.Message);return $false}
}

function Complete-ObservationIfReady([object]$Tx) {
    if(-not $Tx -or $Tx.State -ne 'Observing' -or -not $Tx.ObservationResultPath){return $Tx}
    if(-not (Test-Path -LiteralPath ([string]$Tx.ObservationResultPath))){return $Tx}
    try{$o=Get-Content -LiteralPath ([string]$Tx.ObservationResultPath) -Raw|ConvertFrom-Json}catch{return $Tx}
    if(-not $o.Success){Set-TransactionState $Tx 'NeedsAttention' ("观察期发现新故障：Armoury=$($o.NewArmouryCount), MSI=$($o.NewMsiCount), Service=$($o.BadServiceCount)");return $Tx}
    $v=Get-StrictTransactionVerification $Tx
    if($v.Success){Save-TransactionEvidenceAfter $Tx $v.Snapshot;Set-TransactionState $Tx 'Completed' '60 秒观察期无新错误，严格验证再次 PASS'}
    else{Set-TransactionState $Tx 'NeedsAttention' ('观察期结束但严格验证未通过：'+(@($v.Reasons)-join ' | '))}
    return $Tx
}

function Get-EnvironmentPreflight([string]$Mode='Repair',[string]$Group='') {
    $rows=@()
    function AddP([string]$Name,[string]$Status,[string]$Detail,[bool]$Blocking) {
        $scriptRow=[PSCustomObject]@{Name=$Name;Status=$Status;Detail=$Detail;Blocking=$Blocking}
        $script:__preflightRows += $scriptRow
    }
    $script:__preflightRows=@()

    if (Get-AdminState) {
        AddP '权限模型' 'PASS' '当前进程已提升；Broker/维护模式可执行系统修改' $false
    } elseif (Test-Path -LiteralPath $BrokerPath) {
        AddP '权限模型' 'PASS' 'GUI 以普通权限运行；真正系统修改将由独立 Elevated Repair Broker 重新校验计划后执行' $false
    } else {
        AddP '权限模型' 'BLOCK' 'Elevated Repair Broker 缺失；诊断可继续，但禁止自动修复' $true
    }

    $osv=[Environment]::OSVersion.Version
    if ($osv.Major -ge 10) { AddP 'Windows 版本' 'PASS' ("Windows NT {0}" -f $osv) $false }
    else { AddP 'Windows 版本' 'BLOCK' ("不支持的 Windows 版本 {0}" -f $osv) $true }

    $wid=Get-WindowsIdentity
    AddP 'Windows Build' 'PASS' ("{0} build {1}.{2} / {3}" -f $wid.DisplayVersion,$wid.Build,$wid.UBR,$wid.Edition) $false
    AddP 'Secure Boot' 'INFO' ([string]$wid.SecureBoot) $false

    if ([Environment]::Is64BitOperatingSystem) { AddP '系统架构' 'PASS' '64-bit Windows' $false }
    else {
        $block=($Mode -eq 'ASUS')
        AddP '系统架构' $(if($block){'BLOCK'}else{'WARN'}) '32-bit Windows：ASUS Armoury 自动修复不受支持' $block
    }

    $psv=$PSVersionTable.PSVersion
    if ($psv.Major -gt 5 -or ($psv.Major -eq 5 -and $psv.Minor -ge 1)) { AddP 'PowerShell' 'PASS' ("Windows PowerShell {0}" -f $psv) $false }
    else { AddP 'PowerShell' 'BLOCK' ("需要 PowerShell 5.1，当前 {0}" -f $psv) $true }

    try {
        $driveName=$env:SystemDrive.TrimEnd(':')
        $drv=Get-PSDrive -Name $driveName -ErrorAction Stop
        $gb=[Math]::Round($drv.Free/1GB,2)
        if ($gb -lt 2) { AddP '系统盘空间' 'BLOCK' ("剩余 {0} GB，至少需要 2 GB" -f $gb) $true }
        elseif ($gb -lt 5) { AddP '系统盘空间' 'WARN' ("剩余 {0} GB，建议至少 5 GB" -f $gb) $false }
        else { AddP '系统盘空间' 'PASS' ("剩余 {0} GB" -f $gb) $false }
    } catch { AddP '系统盘空间' 'WARN' '无法读取系统盘剩余空间' $false }

    try {
        $probe=Join-Path $WorkRoot ('write_test_'+[guid]::NewGuid().ToString('N')+'.tmp')
        'ok' | Set-Content -LiteralPath $probe -Encoding ASCII -ErrorAction Stop
        Remove-Item -LiteralPath $probe -Force -ErrorAction SilentlyContinue
        AddP '用户状态目录写权限' 'PASS' $WorkRoot $false
    } catch { AddP '用户状态目录写权限' 'BLOCK' $_.Exception.Message $true }

    $reasons=@(Get-PendingRebootReasons)
    if($reasons.Count -gt 0){$block=($Mode -in @('ASUS','Runtime'));$detail=$reasons -join ', ';if($reasons -contains 'PendingFileRenameOperations'){$allPfr=@(Get-PendingFileRenameDetails);$pfr=@($allPfr|Select-Object -First 4);if($pfr.Count -gt 0){$detail += ' | '+(@($pfr|ForEach-Object{"#$($_.Index) $($_.Operation): $($_.Source) -> $($_.Destination)"}) -join ' ; ');if($allPfr.Count -gt 4){$detail += ' ; ...'}}};AddP '待重启状态' $(if($block){'BLOCK'}else{'WARN'}) $detail $block}else{AddP '待重启状态' 'PASS' '无待重启标记' $false}

    $busy=@()
    foreach($name in @('dism','sfc','setuphost')) {
        try { if(Get-Process -Name $name -ErrorAction SilentlyContinue){$busy+=$name} } catch {}
    }
    $busy=@($busy|Sort-Object -Unique)
    if($busy.Count -gt 0){ AddP '安装/维护进程' 'BLOCK' ("正在运行："+($busy -join ', ')) $true }
    else { AddP '安装/维护进程' 'PASS' '未检测到 DISM / SFC / setuphost 冲突；msiexec 由独立事务判定器分析' $false }

    try {
        $start=(Get-ItemProperty 'HKLM:\SYSTEM\CurrentControlSet\Services\msiserver' -Name Start -ErrorAction Stop).Start
        if([int]$start -eq 4){AddP 'Windows Installer' 'BLOCK' 'msiserver 已被禁用' $true}
        else{AddP 'Windows Installer' 'PASS' ("msiserver Start={0}" -f $start) $false}
    } catch { AddP 'Windows Installer' 'WARN' '无法读取 msiserver 启动配置' $false }

    try {
        if(Get-Process -Name TiWorker -ErrorAction SilentlyContinue){AddP 'Windows Servicing' 'WARN' 'TiWorker 正在运行；建议等待 Windows 维护结束再修复' $false}
        else{AddP 'Windows Servicing' 'PASS' '未检测到 TiWorker 活动' $false}
    } catch {}

    $installerState=Get-InstallerBusyState
    if($installerState.Busy){$desc=@(Get-InstallerBusyEvidence);AddP 'Windows Installer 活动事务' 'BLOCK' ($desc -join '; ') $true}
    elseif(@($installerState.All).Count -gt 0){$desc=@($installerState.All|ForEach-Object{if($_.Kind -eq 'Process'){"PID=$($_.PID) $($_.Reason)"}else{$_.Reason}});AddP 'Windows Installer 进程状态' 'INFO' ($desc -join '; ') $false}
    else{AddP 'Windows Installer 活动事务' 'PASS' '没有足够证据表明 Windows Installer 正在执行活动事务' $false}

    if($Mode -eq 'ASUS' -and $Group){
        $locks=@(Get-RestartManagerLocks $Group)
        $external=@($locks|Where-Object{([string]$_.ServiceName -notin @('ArmouryCrateService','ROG Live Service','LightingService')) -and ([string]$_.AppName -notmatch '(?i)(Armoury|ROG|LightingService|ASUS)')})
        if($external.Count -gt 0){AddP 'Restart Manager 文件占用' 'BLOCK' ((@($external|ForEach-Object{"$($_.AppName) PID=$($_.Pid)"}) -join '; ')) $true}
        elseif($locks.Count -gt 0){AddP 'Restart Manager 文件占用' 'WARN' ((@($locks|ForEach-Object{"$($_.AppName)/$($_.ServiceName) PID=$($_.Pid)"}) -join '; ')) $false}
        else{AddP 'Restart Manager 文件占用' 'PASS' '目标 HAL 文件未被外部进程占用' $false}
    }

    $rows=@($script:__preflightRows)
    Remove-Variable __preflightRows -Scope Script -ErrorAction SilentlyContinue
    return [PSCustomObject]@{CanRepair=(@($rows|Where-Object{$_.Blocking}).Count -eq 0);Rows=$rows;Mode=$Mode;CheckedAt=Get-Date}
}

function Get-PreflightEnvironmentStates([object]$Preflight) {
    $states=@();foreach($x in @($Preflight.Rows|Where-Object{$_.Blocking})){if([string]$x.Name -eq '待重启状态'){$states += 'WAIT_REBOOT';continue};if([string]$x.Name -match 'Installer|安装/维护进程'){$states += 'BUSY';continue};$states += 'BLOCKED'};return @($states|Sort-Object -Unique)
}
function Resolve-EligibilityState([int]$ActionCount,[int]$ManualCount,[object]$Preflight,[string[]]$OtherBlocking) {
    $envStates=@(Get-PreflightEnvironmentStates $Preflight)
    if($ActionCount -eq 0 -and $ManualCount -eq 0){return [PSCustomObject]@{State='NO_ACTION_REQUIRED';EnvironmentStates=$envStates;Decision='当前没有需要自动修复的项目'}}
    if($ActionCount -eq 0 -and $ManualCount -gt 0){return [PSCustomObject]@{State='MANUAL_ONLY';EnvironmentStates=$envStates;Decision='已诊断到问题，但当前身份/版本组合只允许人工处理'}}
    if($envStates -contains 'WAIT_REBOOT'){return [PSCustomObject]@{State='WAIT_REBOOT';EnvironmentStates=$envStates;Decision='存在待重启状态，完成真实重启后再评估修复资格'}}
    if($envStates -contains 'BUSY'){return [PSCustomObject]@{State='BUSY';EnvironmentStates=$envStates;Decision='检测到活动安装/维护事务，等待其结束后再评估'}}
    if(@($OtherBlocking).Count -gt 0 -or $envStates -contains 'BLOCKED'){return [PSCustomObject]@{State='BLOCKED';EnvironmentStates=$envStates;Decision='修复安全门禁未通过'}}
    return [PSCustomObject]@{State='ELIGIBLE';EnvironmentStates=$envStates;Decision='诊断与修复资格门禁均通过，可执行已验证修复计划'}
}

function Get-ASUSRepairEligibility([string]$Group,[object]$Snap) {
    $pre=Get-EnvironmentPreflight 'ASUS' $Group
    $reasons=@();$warnings=@()
    foreach($x in @($pre.Rows)){if($x.Blocking){$reasons += "$($x.Name): $($x.Detail)"}elseif($x.Status -eq 'WARN'){$warnings += "$($x.Name): $($x.Detail)"}}
    if(Get-PendingRepair){$reasons+='已有未完成的 ASUS 修复状态，必须先续跑或人工恢复'}
    $open=Get-LatestOpenTransaction;if($open -and $open.State -notin @('Completed','Failed','NeedsAttention','Cancelled')){$reasons+="存在未闭合事务 $($open.TransactionId) / $($open.State)"}
    $targetRows=@($Snap.Rows|Where-Object{$_.Group -eq $Group -and $_.Status -eq 'REPAIR'})
    if($targetRows.Count -eq 0){$reasons+='没有命中已验证的精确自动修复故障组合'}
    $manual=@($Snap.Rows|Where-Object{$_.Group -eq $Group -and $_.Status -eq 'MANUAL'})
    if($manual.Count -gt 0){$reasons+='同一修复组存在未验证的新版本/未知状态，拒绝套用旧修复规则'}

    foreach($tr in @($targetRows)){
        $d=Get-DefinitionByKey ([string]$tr.Key)
        if(-not $d){continue}
        $inc=@($Snap.ActiveArmoury|Where-Object{$_.Key -eq $d.Key -and $_.Code -eq [string]$d.ExpectedCode})
        if($inc.Count -eq 0){$reasons+="$($d.Key) 没有与当前修复计划匹配的活动 Armoury 事件";continue}
        $profiles=@($inc|ForEach-Object{[string]$_.Profile}|Where-Object{$_}|Sort-Object -Unique)
        if($profiles.Count -gt 0 -and $profiles -notcontains [string]$d.Profile){$reasons+="$($d.Key) 活动事件 Profile 不匹配：actual=$($profiles -join ',') expected=$($d.Profile)"}
        elseif($profiles.Count -eq 0){$warnings+="$($d.Key) 当前日志未暴露 ProfileID；继续使用 ProductCode/安装器/版本/签名/Burn 多因子门禁"}
        $installers=@($inc|ForEach-Object{[string]$_.Installer}|Where-Object{$_}|Sort-Object -Unique)
        if($installers.Count -gt 0 -and $installers -notcontains [string]$d.Exe){$reasons+="$($d.Key) 活动事件安装器不匹配：actual=$($installers -join ',') expected=$($d.Exe)"}
        $targets=@($inc|ForEach-Object{Normalize-VersionText ([string]$_.TargetVersion)}|Where-Object{$_}|Sort-Object -Unique)
        if($targets.Count -gt 0 -and $targets -notcontains [string]$d.VerifiedGood){$reasons+="$($d.Key) 活动事件目标版本不匹配：actual=$($targets -join ',') expected=$($d.VerifiedGood)"}
        $currents=@($inc|ForEach-Object{Normalize-VersionText ([string]$_.CurrentVersion)}|Where-Object{$_}|Sort-Object -Unique)
        if($currents.Count -gt 0){
            $expectedIncidentCurrent=if($d.Key -eq 'ENE'){$d.VerifiedOld}else{$d.VerifiedOld}
            if($currents -notcontains [string]$expectedIncidentCurrent){$reasons+="$($d.Key) 活动事件当前版本不匹配：actual=$($currents -join ',') expected=$expectedIncidentCurrent"}
        }
    }

    $policy=Test-RepairPolicy $Group $targetRows
    $reasons += @($policy.Blocking);$warnings += @($policy.Warnings)
    $manual=@($Snap.Rows|Where-Object{$_.Group -eq $Group -and $_.Status -eq 'MANUAL'})
    $stateInfo=Resolve-EligibilityState $targetRows.Count $manual.Count $pre @($reasons)
    if($stateInfo.State -eq 'NO_ACTION_REQUIRED'){$reasons=@()}
    $eligible=($stateInfo.State -eq 'ELIGIBLE' -and $reasons.Count -eq 0)
    return [PSCustomObject]@{State=$stateInfo.State;Eligible=$eligible;Decision=$stateInfo.Decision;EnvironmentStates=@($stateInfo.EnvironmentStates);Reasons=$reasons;Warnings=$warnings;Preflight=$pre;TargetRows=$targetRows;ManualRows=$manual;Fingerprints=@($policy.Fingerprints);Policy=$policy.Policy}
}


function Get-RuntimeRepairEligibility([object]$Snap) {
    $pre=Get-EnvironmentPreflight 'Runtime' '';$reasons=@();$warnings=@();foreach($x in @($pre.Rows)){if($x.Blocking){$reasons += "$($x.Name): $($x.Detail)"}elseif($x.Status -eq 'WARN'){$warnings += "$($x.Name): $($x.Detail)"}}
    $todo=@($Snap.Rows|Where-Object{$_.Group -eq 'RUNTIME' -and $_.Status -in @('REPAIR','UPDATE','WARN')})
    $stateInfo=Resolve-EligibilityState $todo.Count 0 $pre @($reasons)
    if($stateInfo.State -eq 'NO_ACTION_REQUIRED'){$reasons=@()}
    $eligible=($stateInfo.State -eq 'ELIGIBLE' -and $reasons.Count -eq 0)
    $decision=if($todo.Count -gt 0){'运行库不完整或版本偏低，可以自动修复。'}else{'运行库正常，不必修复。'}
    return [PSCustomObject]@{State=$stateInfo.State;Eligible=$eligible;Decision=$decision;EnvironmentStates=@($stateInfo.EnvironmentStates);Reasons=$reasons;Warnings=$warnings;Preflight=$pre;TargetRows=$todo}
}


function Convert-PlanRows([object[]]$Rows) {
    $out=@()
    foreach($r in @($Rows)){
        $out += [PSCustomObject]@{Key=$r.Key;Name=$r.Name;Installed=$r.Installed;Target=$r.Target;Runtime=$r.Runtime;Status=$r.Status;ErrorCode=$r.ErrorCode}
    }
    return $out
}

function New-RepairPlan([ValidateSet('ASUS','RUNTIME')][string]$Type,[string]$Group,[object]$Snap) {
    $id='PLAN-'+(Get-Date -Format 'yyyyMMdd-HHmmss')+'-'+([guid]::NewGuid().ToString('N').Substring(0,6));$actions=@();$recovery=@();$risk='LOW';$elig=$null;$label='';$moduleIdentity=$null;$runtimePackages=@()
    if($Type -eq 'ASUS'){$elig=Get-ASUSRepairEligibility $Group $Snap;$info=Get-ModuleInfo $Group;$label=if($info){$info.Label}else{$Group};if($info -and(Test-Path -LiteralPath $info.Module)){try{$policy=$RepairPolicies[$Group];$moduleKey=[string]$policy.ModuleKey;$moduleIdentity=[PSCustomObject]@{Path=$info.Module;SHA256=(Get-FileHash -Algorithm SHA256 -LiteralPath $info.Module).Hash.ToLowerInvariant();ExpectedSHA256=[string]$ExpectedModuleHashes[$moduleKey];Label=$info.Label}}catch{}};$actions=@('确认奥创组件身份','按已验证步骤修复','修完后再看有没有新的更新错误');$recovery=@('用本工具生成的恢复包还原','需要时使用系统还原点');$risk='MEDIUM'}else{$elig=Get-RuntimeRepairEligibility $Snap;$label='游戏运行库';$actions=@('检测本机 C++ 运行库和 DirectX','能修的项目自动修','优先用本机安装包，没有再尝试安装','修完后再检测一次');$recovery=@('需要时再自行安装官方运行库');$risk='LOW'}
    $plan=[PSCustomObject]@{SchemaVersion=2;PlanId=$id;AppVersion=$AppVersion;BuildId=$BuildId;EngineSHA256=$script:EngineSHA256;CreatedAt=(Get-Date).ToString('o');Type=$Type;Group=$Group;Label=$label;PlanState=[string]$elig.State;EnvironmentStates=@($elig.EnvironmentStates);Decision=[string]$elig.Decision;Eligible=[bool]$elig.Eligible;BlockingReasons=@($elig.Reasons);Warnings=@($elig.Warnings);Risk=$risk;Actions=$actions;Recovery=$recovery;TargetRows=Convert-PlanRows $elig.TargetRows;Fingerprints=$(if($Type -eq 'ASUS'){@($elig.Fingerprints)}else{@()});Policy=$(if($Type -eq 'ASUS'){$elig.Policy}else{$null});RepairModuleIdentity=$moduleIdentity;RuntimePackageIdentities=@($runtimePackages)}
    $path=Join-Path $PlanRoot ($id+'.json');try{[void](Write-JsonAtomic $path $plan 16)}catch{};$script:CurrentPlan=$plan;return $plan
}

function ConvertTo-CustomerSentence([string]$Text) {
    if(-not $Text){return ''}
    $t=[string]$Text
    $t=$t -replace '(?i)NO_ACTION_REQUIRED','不必修复'
    $t=$t -replace '(?i)WAIT_REBOOT','需要先重启'
    $t=$t -replace '(?i)MANUAL_ONLY','只能人工处理'
    $t=$t -replace 'https?://\S+',''
    $t=$t -replace '[A-Za-z]:\\[^\s]+','本机文件'
    $t=$t -replace '\\\\[^\s]+','本机文件'
    $t=$t -replace '\b[0-9a-fA-F]{64}\b',''
    $t=$t -replace 'SHA256=\S+',''
    $t=$t -replace 'ProductCode=\S+',''
    $t=$t -replace 'UpgradeCode=\S+',''
    $t=$t -replace 'Thumbprint=\S+',''
    $t=$t -replace 'Authenticode','签名'
    $t=$t -replace '\s+',' '
    return $t.Trim()
}

function Format-RepairPlan([object]$Plan) {
    if(-not $Plan){return '还没有检测结论。'}
    $state=[string]$Plan.PlanState
    $eligible=[bool]$Plan.Eligible
    $lines=New-Object System.Collections.ArrayList
    if($eligible){[void]$lines.Add('结论：需要修复，而且可以自动修')}
    elseif($state -eq 'NO_ACTION_REQUIRED'){[void]$lines.Add('结论：不必修复')}
    elseif($state -in @('MANUAL_ONLY','MANUAL')){[void]$lines.Add('结论：发现了问题，但不能自动修')}
    elseif($state -eq 'WAIT_REBOOT'){[void]$lines.Add('结论：先重启电脑，再回来检测')}
    elseif($state -eq 'BUSY'){[void]$lines.Add('结论：现在有别的安装在进行，等它结束后再测')}
    elseif($state -eq 'BLOCKED'){[void]$lines.Add('结论：现在不能修')}
    else{[void]$lines.Add('结论：暂不修复')}
    [void]$lines.Add('')
    $decision=ConvertTo-CustomerSentence ([string]$Plan.Decision)
    if($decision){[void]$lines.Add($decision)}
    $targets=@($Plan.TargetRows)
    if($targets.Count -gt 0){
        [void]$lines.Add('')
        [void]$lines.Add('涉及项目：')
        foreach($r in $targets){
            $name=[string]$r.Name
            $detail=ConvertTo-CustomerSentence ([string]$r.Runtime)
            if(-not $detail){$detail=ConvertTo-CustomerSentence ([string]$r.Status)}
            [void]$lines.Add(('  · {0}：{1}' -f $name,$detail))
        }
    }
    $blocks=@($Plan.BlockingReasons)
    if($blocks.Count -gt 0 -and $state -ne 'NO_ACTION_REQUIRED'){
        [void]$lines.Add('')
        [void]$lines.Add('原因：')
        foreach($x in $blocks){[void]$lines.Add('  · '+(ConvertTo-CustomerSentence ([string]$x)))}
    }
    if($eligible){
        [void]$lines.Add('')
        if([string]$Plan.Type -eq 'RUNTIME'){[void]$lines.Add('接下来：点「修复运行库」，然后在系统确认窗口同意。');[void]$lines.Add('修完后再检测一次。')}else{[void]$lines.Add('接下来：点「执行安全修复」，然后在系统确认窗口同意。');[void]$lines.Add('修完后再看一次，有没有新的更新错误。')}
    } elseif($state -eq 'NO_ACTION_REQUIRED'){
        [void]$lines.Add('现在不用动手。')
    }
    return (($lines.ToArray()) -join "`r`n")
}


function Save-Transaction([object]$Tx) {
    if(-not $Tx){return}
    $folder=Join-Path $TransactionRoot ([string]$Tx.TransactionId);New-Item -ItemType Directory -Force -Path $folder|Out-Null
    [void](Write-JsonAtomic (Join-Path $folder 'state.json') $Tx 20)
}

function Write-TransactionEvent([object]$Tx,[string]$Event,[string]$Detail) {
    if(-not $Tx){return}
    $folder=Join-Path $TransactionRoot ([string]$Tx.TransactionId);$journal=Join-Path $folder 'Journal';New-Item -ItemType Directory -Force -Path $journal|Out-Null
    $seq=1;try{$seq=[int]$Tx.SequenceNumber}catch{};$prev='';try{$prev=[string]$Tx.LastJournalHash}catch{}
    $core=[PSCustomObject]@{SchemaVersion=2;Sequence=$seq;At=(Get-Date).ToString('o');Event=$Event;Detail=$Detail;PreviousHash=$prev}
    $coreText=$core|ConvertTo-Json -Compress -Depth 8;$hash=Get-SHA256Text $coreText
    $obj=[PSCustomObject]@{SchemaVersion=2;Sequence=$seq;At=$core.At;Event=$Event;Detail=$Detail;PreviousHash=$prev;Hash=$hash}
    $name=('{0:D6}_{1}.json' -f $seq,($Event -replace '[^A-Za-z0-9_-]','_'))
    [void](Write-JsonAtomic (Join-Path $journal $name) $obj 8)
    try{($obj|ConvertTo-Json -Compress)|Add-Content -LiteralPath (Join-Path $folder 'events.jsonl') -Encoding UTF8}catch{}
    $Tx|Add-Member -NotePropertyName LastJournalHash -NotePropertyValue $hash -Force
}

function Set-TransactionState([object]$Tx,[string]$State,[string]$Detail='') {
    if(-not $Tx){return}
    $seq=0;try{$seq=[int]$Tx.SequenceNumber}catch{};$seq++
    $Tx|Add-Member -NotePropertyName SequenceNumber -NotePropertyValue $seq -Force
    $Tx|Add-Member -NotePropertyName State -NotePropertyValue $State -Force
    $Tx|Add-Member -NotePropertyName UpdatedAt -NotePropertyValue ((Get-Date).ToString('o')) -Force
    $Tx|Add-Member -NotePropertyName LastDetail -NotePropertyValue $Detail -Force
    if($State -in @('SuccessPendingVerification','NeedsVerification') -and -not $Tx.VerificationStartAt){$Tx|Add-Member -NotePropertyName VerificationStartAt -NotePropertyValue ((Get-Date).ToString('o')) -Force}
    Write-TransactionEvent $Tx $State $Detail
    Save-Transaction $Tx
    $script:CurrentTransaction=$Tx
}

function New-RepairTransaction([object]$Plan,[object]$Snap) {
    $id='TX-'+(Get-Date -Format 'yyyyMMdd-HHmmss')+'-'+([guid]::NewGuid().ToString('N').Substring(0,8))
    $manifestPath=Join-Path $RulePackRoot 'BuiltIn_ComponentIdentityManifest.json'
    $manifestHash='';if(Test-Path -LiteralPath $manifestPath){try{$manifestHash=(Get-FileHash -Algorithm SHA256 -LiteralPath $manifestPath).Hash}catch{}}
    $tx=[PSCustomObject]@{SchemaVersion=4;TransactionId=$id;AppVersion=$AppVersion;BuildId=$BuildId;EngineSHA256=$script:EngineSHA256;BuildInfoSHA256=$script:BuildInfoSHA256;BrokerSHA256=$ExpectedBrokerSHA256;PlanId=$Plan.PlanId;Type=$Plan.Type;Group=$Plan.Group;Label=$Plan.Label;State='Created';StartedAt=(Get-Date).ToString('o');UpdatedAt=(Get-Date).ToString('o');LastDetail='';SequenceNumber=1;LastJournalHash='';VerificationStartAt='';BeforeRows=Convert-PlanRows $Snap.Rows;Plan=$Plan;BootTimeBefore=Get-BootTimeText;IdentityManifestSHA256=$manifestHash}
    Save-Transaction $tx;Write-TransactionEvent $tx 'Created' '事务已建立；尚未执行破坏性操作';Save-Transaction $tx
    Save-TransactionEvidenceBefore $tx $Snap
    Set-TransactionState $tx 'Prepared' '事务证据包已建立：系统/服务/MSI/Burn/安装器指纹/注册表/恢复副本已记录'
    $script:CurrentTransaction=$tx;return $tx
}

function Test-TransactionJournalIntegrity([object]$Tx) {
    if(-not $Tx){return [PSCustomObject]@{Valid=$false;Detail='No transaction';Count=0}}
    $folder=Join-Path (Join-Path $TransactionRoot ([string]$Tx.TransactionId)) 'Journal'
    if(-not (Test-Path -LiteralPath $folder)){return [PSCustomObject]@{Valid=$false;Detail='Journal folder missing';Count=0}}
    $prev='';$expectedSeq=1;$count=0
    try{
        $files=@(Get-ChildItem -LiteralPath $folder -File -Filter '*.json' -ErrorAction Stop|Sort-Object Name)
        foreach($f in $files){
            $o=Get-Content -LiteralPath $f.FullName -Raw -ErrorAction Stop|ConvertFrom-Json
            $seq=[int]$o.Sequence
            if($seq -ne $expectedSeq){return [PSCustomObject]@{Valid=$false;Detail="Journal sequence mismatch at $($f.Name): actual=$seq expected=$expectedSeq";Count=$count}}
            if([string]$o.PreviousHash -ne $prev){return [PSCustomObject]@{Valid=$false;Detail="Journal PreviousHash mismatch at $($f.Name)";Count=$count}}
            $core=[PSCustomObject]@{SchemaVersion=[int]$o.SchemaVersion;Sequence=$seq;At=[string]$o.At;Event=[string]$o.Event;Detail=[string]$o.Detail;PreviousHash=[string]$o.PreviousHash}
            $calc=Get-SHA256Text ($core|ConvertTo-Json -Compress -Depth 8)
            if($calc -ne [string]$o.Hash){return [PSCustomObject]@{Valid=$false;Detail="Journal hash mismatch at $($f.Name)";Count=$count}}
            $prev=[string]$o.Hash;$expectedSeq++;$count++
        }
        if($count -eq 0){return [PSCustomObject]@{Valid=$false;Detail='Journal is empty';Count=0}}
        if($Tx.LastJournalHash -and [string]$Tx.LastJournalHash -ne $prev){return [PSCustomObject]@{Valid=$false;Detail='state.json LastJournalHash does not match journal tail';Count=$count}}
        return [PSCustomObject]@{Valid=$true;Detail='Journal hash chain PASS';Count=$count;TailHash=$prev}
    }catch{return [PSCustomObject]@{Valid=$false;Detail=$_.Exception.Message;Count=$count}}
}

function Get-RecentTransactions([int]$Max=30) {
    $out=@()
    try{
        $files=Get-ChildItem -LiteralPath $TransactionRoot -Recurse -File -Filter 'state.json' -ErrorAction SilentlyContinue|Sort-Object LastWriteTime -Descending|Select-Object -First $Max
        foreach($f in $files){try{$out += Get-Content -LiteralPath $f.FullName -Raw -ErrorAction Stop|ConvertFrom-Json}catch{}}
    }catch{}
    return $out
}

function Get-LatestOpenTransaction {
    $closed=@('Completed','Failed','NeedsAttention','Cancelled')
    return (Get-RecentTransactions 50|Where-Object{$_.State -notin $closed}|Sort-Object UpdatedAt -Descending|Select-Object -First 1)
}

function Find-LatestFixStatus([string]$Pattern,[datetime]$After) {
    try{
        $dirs=Get-ChildItem $Desktop -Directory -Filter $Pattern -ErrorAction SilentlyContinue|Where-Object{$_.LastWriteTime -ge $After.AddMinutes(-2)}|Sort-Object LastWriteTime -Descending
        foreach($d in $dirs){$p=Join-Path $d.FullName 'FIX_STATUS.txt';if(Test-Path -LiteralPath $p){return [PSCustomObject]@{Status=(Get-Content -LiteralPath $p -Raw).Trim();Dir=$d.FullName}}}
    }catch{}
    return $null
}

function Sync-OpenTransactionState {
    $tx=Get-LatestOpenTransaction
    if(-not $tx){return $null}
    $ji=Test-TransactionJournalIntegrity $tx
    if(-not $ji.Valid){
        $tx.State='NeedsAttention';$tx.UpdatedAt=(Get-Date).ToString('o');$tx.LastDetail=('事务 Journal 完整性校验失败：'+$ji.Detail);Save-Transaction $tx
        return $tx
    }
    if($tx.State -eq 'Observing'){return (Complete-ObservationIfReady $tx)}
    if($tx.Type -eq 'ASUS' -and $tx.Group){
        $internal=Get-ModuleInternalState ([string]$tx.Group)
        if($internal){
            $phase=[string]$internal.Phase
            $mapped=''
            switch -Regex ($phase){
                '^Prepared$' {$mapped='ModulePrepared'}
                '^Uninstalling$' {$mapped='Uninstalling'}
                '^AwaitingReboot$' {$mapped='AwaitingReboot'}
                '^(Completed|Success)$' {$mapped='SuccessPendingVerification'}
                '^(Failed|Aborted)$' {$mapped='NeedsAttention'}
            }
            if($mapped -and $tx.State -ne $mapped){Set-TransactionState $tx $mapped ("底层模块状态同步: $phase / $($internal.StatePath)")}
        }
        $info=Get-ModuleInfo ([string]$tx.Group)
        if($info){
            $start=[datetime]::MinValue;try{$start=[datetime]$tx.StartedAt}catch{}
            $fx=Find-LatestFixStatus $info.Pattern $start
            if($fx){
                if($fx.Status -eq 'SUCCESS' -and $tx.State -ne 'SuccessPendingVerification'){Set-TransactionState $tx 'SuccessPendingVerification' ("模块报告 SUCCESS: "+$fx.Dir)}
                elseif($fx.Status -eq 'AWAITING_REBOOT' -and $tx.State -ne 'AwaitingReboot'){Set-TransactionState $tx 'AwaitingReboot' '模块阶段1完成，等待真实重启'}
                elseif($fx.Status -match '^FAILED' -and $tx.State -ne 'NeedsAttention'){Set-TransactionState $tx 'NeedsAttention' ("模块状态 "+$fx.Status)}
            }
        }
    } elseif($tx.Type -eq 'RUNTIME' -and $tx.State -eq 'RepairStarted') {
        $busy=@(Get-InstallerBusyEvidence);if($busy.Count -eq 0){Set-TransactionState $tx 'NeedsAttention' '上次运行库修复在 RepairStarted 阶段中断；为避免重复安装，要求重新诊断后人工确认'}
    }
    return $tx
}

function Save-IncidentHistory([object[]]$Incidents) {
    if(-not $script:IncidentDbInitialized){
        $script:IncidentDbInitialized=$true
        if(Test-Path -LiteralPath $IncidentDbPath){
            try{
                foreach($line in @(Get-Content -LiteralPath $IncidentDbPath -Tail 4000 -ErrorAction Stop)){
                    try{$old=$line|ConvertFrom-Json;if($old.DedupKey){$script:IncidentSeen[[string]$old.DedupKey]=$true}}catch{}
                }
            }catch{}
        }
    }
    foreach($x in @($Incidents)){
        $k=[string]$x.DedupKey
        if(-not $k){$k=([string]$x.File)+'|'+([string]$x.Line)}
        if($script:IncidentSeen.ContainsKey($k)){continue}
        $script:IncidentSeen[$k]=$true
        $obj=[PSCustomObject]@{SchemaVersion=2;EngineVersion=$AppVersion;BuildId=$BuildId;EngineSHA256=$script:EngineSHA256;RecordedAt=(Get-Date).ToString('o');ObservedAt=$x.ObservedAt;Code=$x.Code;Key=$x.Key;Profile=$x.Profile;Component=$x.Component;CurrentVersion=$x.CurrentVersion;TargetVersion=$x.TargetVersion;File=$x.File;DedupKey=$k}
        try{($obj|ConvertTo-Json -Compress)|Add-Content -LiteralPath $IncidentDbPath -Encoding UTF8}catch{}
    }
    try{
        $fi=Get-Item -LiteralPath $IncidentDbPath -ErrorAction SilentlyContinue
        if($fi -and $fi.Length -gt 5MB){$tail=Get-Content -LiteralPath $IncidentDbPath -Tail 4000; $tail|Set-Content -LiteralPath $IncidentDbPath -Encoding UTF8}
    }catch{}
}

function Initialize-DirectXSmokeType {
    if($script:NativeSmokeLoaded){return $true}
    $cs=@'
using System;
using System.Runtime.InteropServices;
public static class GameRuntimeNativeSmoke {
    [DllImport("dxgi.dll", ExactSpelling=true)] static extern int CreateDXGIFactory1(ref Guid riid, out IntPtr ppFactory);
    [DllImport("d3d11.dll", ExactSpelling=true)] static extern int D3D11CreateDevice(IntPtr pAdapter, int DriverType, IntPtr Software, uint Flags, IntPtr pFeatureLevels, uint FeatureLevels, uint SDKVersion, out IntPtr ppDevice, out int pFeatureLevel, out IntPtr ppImmediateContext);
    [DllImport("d3d12.dll", ExactSpelling=true)] static extern int D3D12CreateDevice(IntPtr pAdapter, int MinimumFeatureLevel, ref Guid riid, out IntPtr ppDevice);
    static int Missing(){return unchecked((int)0x8007007E);} 
    public static int TestDXGI(){IntPtr p=IntPtr.Zero;try{Guid g=new Guid("770aae78-f26f-4dba-a829-253c83d1b387");int h=CreateDXGIFactory1(ref g,out p);if(p!=IntPtr.Zero)Marshal.Release(p);return h;}catch{return Missing();}}
    public static int TestD3D11(int driverType){IntPtr d=IntPtr.Zero;IntPtr c=IntPtr.Zero;int fl=0;try{int h=D3D11CreateDevice(IntPtr.Zero,driverType,IntPtr.Zero,0,IntPtr.Zero,0,7,out d,out fl,out c);if(c!=IntPtr.Zero)Marshal.Release(c);if(d!=IntPtr.Zero)Marshal.Release(d);return h;}catch{return Missing();}}
    public static int TestD3D12(){IntPtr d=IntPtr.Zero;try{Guid g=new Guid("189819f1-1db6-4b57-be54-1821339b85f7");int h=D3D12CreateDevice(IntPtr.Zero,0xb000,ref g,out d);if(d!=IntPtr.Zero)Marshal.Release(d);return h;}catch{return Missing();}}
}
'@
    try{Add-Type -TypeDefinition $cs -Language CSharp -ErrorAction Stop|Out-Null;$script:NativeSmokeLoaded=$true;return $true}catch{return $false}
}

function Format-HResult([int]$Hr){try{$u=[BitConverter]::ToUInt32([BitConverter]::GetBytes($Hr),0);return ('0x{0:X8}' -f $u)}catch{return [string]$Hr}}
function Test-HResultOK([int]$Hr){return ($Hr -ge 0)}

function Invoke-DirectXAPISmokeTest {
    if(-not (Initialize-DirectXSmokeType)){return [PSCustomObject]@{Category='DirectX API';Test='Native API create-device';Status='FAIL';Detail='无法编译/加载 DirectX PInvoke 测试类型'}}
    $dxgi=[GameRuntimeNativeSmoke]::TestDXGI();$hw=[GameRuntimeNativeSmoke]::TestD3D11(1);$warp=[GameRuntimeNativeSmoke]::TestD3D11(5);$d12=[GameRuntimeNativeSmoke]::TestD3D12()
    $status='PASS'
    if(-not (Test-HResultOK $dxgi) -or ((-not (Test-HResultOK $hw)) -and (-not (Test-HResultOK $warp)))){$status='FAIL'}
    elseif(-not (Test-HResultOK $hw) -or -not (Test-HResultOK $d12)){$status='WARN'}
    $detail="DXGI=$(Format-HResult $dxgi); D3D11-HW=$(Format-HResult $hw); D3D11-WARP=$(Format-HResult $warp); D3D12=$(Format-HResult $d12)"
    if($status -eq 'WARN' -and (Test-HResultOK $warp) -and -not (Test-HResultOK $hw)){$detail+='；WARP 可用但硬件 D3D11 创建失败，优先检查显卡驱动/设备'}
    if($status -eq 'WARN' -and -not (Test-HResultOK $d12)){$detail+='；D3D12 设备创建失败可能是 GPU/驱动能力，不等同于 DirectX 系统文件损坏'}
    return [PSCustomObject]@{Category='DirectX API';Test='DXGI/D3D11/D3D12 真实创建设备';Status=$status;Detail=$detail}
}

function Write-VCRuntimeSmokeWorker {
    $p=Join-Path $WorkRoot 'VCRuntimeSmokeWorker.ps1'
    $w=@'
param([string]$Arch,[string]$OutPath)
$ErrorActionPreference='Stop'
Add-Type -TypeDefinition @"
using System;using System.Runtime.InteropServices;public static class L{[DllImport("kernel32.dll",CharSet=CharSet.Unicode,SetLastError=true)]public static extern IntPtr LoadLibraryW(string p);[DllImport("kernel32.dll",CharSet=CharSet.Ansi,SetLastError=true)]public static extern IntPtr GetProcAddress(IntPtr h,string n);[DllImport("kernel32.dll")]public static extern bool FreeLibrary(IntPtr h);}
"@
$root=Join-Path $env:WINDIR $(if($Arch -eq 'x86' -and [Environment]::Is64BitOperatingSystem){'SysWOW64'}else{'System32'})
$names=@('vcruntime140.dll','msvcp140.dll');if($Arch -ne 'x86'){$names+='vcruntime140_1.dll'}
$rows=@();$ok=$true
foreach($n in $names){$path=Join-Path $root $n;$h=[IntPtr]::Zero;$err=0;if(Test-Path -LiteralPath $path){$h=[L]::LoadLibraryW($path);if($h -eq [IntPtr]::Zero){$err=[Runtime.InteropServices.Marshal]::GetLastWin32Error();$ok=$false}else{$probe=$true;if($n -ieq 'vcruntime140.dll'){$gp=[L]::GetProcAddress($h,'memcpy');if($gp -eq [IntPtr]::Zero){$probe=$false;$ok=$false;$err=[Runtime.InteropServices.Marshal]::GetLastWin32Error()}};[void][L]::FreeLibrary($h)}}else{$ok=$false;$err=2};$rows+=[pscustomobject]@{File=$path;Loaded=($h -ne [IntPtr]::Zero);Win32Error=$err}}
[pscustomobject]@{Arch=$Arch;Success=$ok;Rows=$rows}|ConvertTo-Json -Depth 5|Set-Content -LiteralPath $OutPath -Encoding UTF8
exit $(if($ok){0}else{2})
'@
    try{$w|Set-Content -LiteralPath $p -Encoding UTF8;return $p}catch{return ''}
}

function Invoke-VCRuntimeLoadSmokeTest([string]$Arch) {
    if($Arch -eq 'arm64'){return [PSCustomObject]@{Category='VC++ Load';Test='arm64 DLL Loader';Status='INFO';Detail='当前版本暂不在 x64 进程内执行原生 ARM64 Loader 测试；仍执行注册表/签名检查'}}
    $worker=Write-VCRuntimeSmokeWorker;if(-not $worker){return [PSCustomObject]@{Category='VC++ Load';Test="$Arch DLL Loader";Status='FAIL';Detail='无法生成 Loader 测试脚本'}}
    $out=Join-Path $DeepTestRoot ("vc_load_${Arch}_"+(Get-Date -Format 'yyyyMMddHHmmss')+'.json')
    $ps=Join-Path $env:WINDIR 'System32\WindowsPowerShell\v1.0\powershell.exe'
    if($Arch -eq 'x86' -and [Environment]::Is64BitOperatingSystem){$ps=Join-Path $env:WINDIR 'SysWOW64\WindowsPowerShell\v1.0\powershell.exe'}
    try{
        $args="-NoProfile -ExecutionPolicy Bypass -File `"$worker`" -Arch $Arch -OutPath `"$out`""
        $p=Start-Process -FilePath $ps -ArgumentList $args -PassThru -WindowStyle Hidden
        $pCode=Wait-ProcessResponsive $p
        if(-not (Test-Path -LiteralPath $out)){throw "worker exit=$pCode no result"}
        $r=Get-Content -LiteralPath $out -Raw|ConvertFrom-Json
        $detail=@($r.Rows|ForEach-Object{"$([IO.Path]::GetFileName($_.File))=$(if($_.Loaded){'Loaded'}else{"FAIL:$($_.Win32Error)"})"}) -join '; '
        return [PSCustomObject]@{Category='VC++ Load';Test="$Arch 真实 DLL Loader";Status=$(if($r.Success){'PASS'}else{'FAIL'});Detail=$detail}
    }catch{return [PSCustomObject]@{Category='VC++ Load';Test="$Arch 真实 DLL Loader";Status='FAIL';Detail=$_.Exception.Message}}
}

function Invoke-GameRuntimeDeepTest {
    $rows=@()
    foreach($a in @(Get-RequiredVCRedistArchitectures)){$rows += Invoke-VCRuntimeLoadSmokeTest $a}
    $rows += Invoke-DirectXAPISmokeTest
    try{
        $display=@(Get-PnpDevice -Class Display -ErrorAction SilentlyContinue)
        if($display.Count -eq 0){$rows += [PSCustomObject]@{Category='GPU';Test='Display PnP';Status='WARN';Detail='未读取到 Display 设备'}}
        else{foreach($d in $display){$rows += [PSCustomObject]@{Category='GPU';Test=[string]$d.FriendlyName;Status=$(if($d.Status -eq 'OK'){'PASS'}else{'WARN'});Detail=("PnP Status="+[string]$d.Status)}}}
    }catch{$rows += [PSCustomObject]@{Category='GPU';Test='Display PnP';Status='WARN';Detail='无法读取 PnP 显卡状态'}}
    $obj=[PSCustomObject]@{SchemaVersion=2;Version=$AppVersion;BuildId=$BuildId;EngineSHA256=$script:EngineSHA256;CheckedAt=(Get-Date).ToString('o');Rows=$rows}
    try{$obj|ConvertTo-Json -Depth 8|Set-Content -LiteralPath $DeepTestLastPath -Encoding UTF8}catch{}
    return $rows
}

function Get-StrictTransactionVerification([object]$Tx) {
    if(-not $Tx){return [PSCustomObject]@{Success=$false;Reasons=@('没有事务')}}
    $reasons=@();$snap=Get-SystemSnapshot -Force
    $start=[datetime]::MinValue
    try{if($Tx.VerificationStartAt){$start=[datetime]$Tx.VerificationStartAt}else{$start=[datetime]$Tx.UpdatedAt}}catch{}
    if($Tx.Type -eq 'ASUS'){
        $newArm=@(Get-ArmouryErrorEvidence 180|Where-Object{$_.ObservedAt -gt $start})
        $newMsi=@(Get-RecentMsiErrors 180|Where-Object{$_.ObservedAt -gt $start})
        if($newArm.Count -gt 0){$reasons += "验证窗口仍出现 $($newArm.Count) 个 Armoury 4xxx/版本错误"}
        if($newMsi.Count -gt 0){$reasons += "验证窗口仍出现 $($newMsi.Count) 个 MSI 1603/1618/1721/11721 错误"}
        foreach($r in @($Tx.Plan.TargetRows)){
            $d=Get-DefinitionByKey ([string]$r.Key);if(-not $d){$reasons += "缺少组件定义 $($r.Key)";continue}
            $fp=Get-ComponentFingerprint $d -IncludeRuntime -Force
            if(-not $fp.MSI.Registered){$reasons += "$($d.Name) MSI 未注册"}
            if($fp.MSI.Registered -and [string]$fp.MSI.Publisher -and [string]$d.SignerRegex -and ([string]$fp.MSI.Publisher -notmatch [string]$d.SignerRegex)){$reasons += "$($d.Name) MSI Publisher 异常: $($fp.MSI.Publisher)"}
            $preFp=@($Tx.Plan.Fingerprints|Where-Object{$_.Key -eq $d.Key}|Select-Object -First 1)
            if(-not $preFp -or -not $preFp.TargetInstaller -or -not $preFp.TargetInstaller.Trust -or -not $preFp.TargetInstaller.Trust.Valid){$reasons += "$($d.Name) 事务中没有可信的修复前目标安装器身份证据"}
            if($fp.TargetInstaller.Found){
                if(-not $fp.TargetInstaller.Trust.Valid){$reasons += "$($d.Name) 修复后仍存在的目标安装器签名复核失败"}
                elseif((Normalize-VersionText ([string]$fp.TargetInstaller.Trust.ProductVersion)) -ne [string]$d.VerifiedGood -and (Normalize-VersionText ([string]$fp.TargetInstaller.Trust.FileVersion)) -ne [string]$d.VerifiedGood){$reasons += "$($d.Name) 目标安装器版本复核不等于 $($d.VerifiedGood)"}
            }
            elseif([string]$fp.MSI.Version -ne [string]$d.VerifiedGood){$reasons += "$($d.Name) MSI=$($fp.MSI.Version)，目标=$($d.VerifiedGood)"}
            if($d.TargetBundleId -and -not $fp.TargetBundle.Registered){$reasons += "$($d.Name) 目标 Burn Provider 未注册：$($d.TargetBundleId)"}
            elseif(-not $d.TargetBundleId){
                # For PV components the target bundle GUID was not captured in the original incident; require at least a matching current Burn/ARP display version if one is discoverable, otherwise rely on MSI+runtime+logs.
                $matches=@()
                try{$matches=@(Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*','HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*' -ErrorAction SilentlyContinue|Where-Object{([string]$_.DisplayName -match [regex]::Escape([string]$d.Name)) -and ([string]$_.DisplayVersion -eq [string]$d.VerifiedGood)})}catch{}
                if($matches.Count -eq 0){$reasons += "$($d.Name) 未找到与目标版本匹配的 Burn/ARP 注册证据"}
            }
            if($d.Key -eq 'ENE'){
                $x64=Get-FileVersionSafe 'C:\Program Files\ENE\Aac_ENE_EHD_M2_HAL\AacHal_x64.dll';$x86=Get-FileVersionSafe 'C:\Program Files\ENE\Aac_ENE_EHD_M2_HAL\AacHal_x86.dll'
                if($x64 -ne $d.VerifiedGood -or $x86 -ne $d.VerifiedGood){$reasons += "ENE 实际 DLL 不一致 x64=$x64 x86=$x86"}
            } else {
                $runtime=@($fp.RuntimeFiles);if($runtime.Count -eq 0){$reasons += "$($d.Name) 安装目录没有可验证 DLL/EXE 运行文件"}
                else{
                    $badSig=@($runtime|Where-Object{$_.Signature -notin @('Valid','NotSigned') -and $_.Signature});if($badSig.Count -gt 0){$reasons += "$($d.Name) 运行文件存在签名异常=$($badSig.Count)"}
                    $versioned=@($runtime|Where-Object{(Normalize-VersionText ([string]$_.FileVersion)) -eq [string]$d.VerifiedGood -or (Normalize-VersionText ([string]$_.ProductVersion)) -eq [string]$d.VerifiedGood})
                    if($versioned.Count -eq 0){$reasons += "$($d.Name) 未在安装目录找到目标版本 DLL/EXE 证据 $($d.VerifiedGood)"}
                }
            }
        }
        foreach($n in @('ArmouryCrateService','ROG Live Service','LightingService')){
            $svc=Get-Service -Name $n -ErrorAction SilentlyContinue
            if(-not $svc){$reasons += "$n 服务不存在"}
            elseif($svc.Status -ne 'Running'){$reasons += "$n 未运行：$($svc.Status)"}
        }
    } else {
        $remain=@($snap.Rows|Where-Object{$_.Group -eq 'RUNTIME' -and $_.Status -in @('REPAIR','UPDATE','WARN')})
        if($remain.Count -gt 0){$reasons += ('运行库仍有待处理项：'+(@($remain|ForEach-Object{$_.Name+'='+$_.Status}) -join ', '))}
        $deep=@(Invoke-GameRuntimeDeepTest|Where-Object{$_.Status -eq 'FAIL'})
        if($deep.Count -gt 0){$reasons += ('深度加载/API 测试仍失败：'+(@($deep|ForEach-Object{$_.Test}) -join ', '))}
    }
    return [PSCustomObject]@{Success=($reasons.Count -eq 0);Reasons=$reasons;Snapshot=$snap;VerificationStart=$start}
}

function Get-PendingFileRenameDetails {
    $out=@();try{$raw=@((Get-ItemProperty 'HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager' -Name PendingFileRenameOperations -ErrorAction Stop).PendingFileRenameOperations);for($i=0;$i -lt $raw.Count;$i+=2){$src=[string]$raw[$i];$dst='';if($i+1 -lt $raw.Count){$dst=[string]$raw[$i+1]};$op=if(-not $dst){'DELETE'}else{'RENAME/REPLACE'};$out += [PSCustomObject]@{Index=[int]($i/2);Operation=$op;Source=$src;Destination=$dst}}}catch{};return $out
}

function Get-PendingRebootReasons {
    $r=@();if(Test-Path 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Component Based Servicing\RebootPending'){$r += 'CBS'};if(Test-Path 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\WindowsUpdate\Auto Update\RebootRequired'){$r += 'WindowsUpdate'};if(@(Get-PendingFileRenameDetails).Count -gt 0){$r += 'PendingFileRenameOperations'};return $r
}

function Get-RecentMsiErrors([int]$Minutes=60) {
    $out = @()
    $seen = @{}
    $since = (Get-Date).AddMinutes(-1 * $Minutes)
    try {
        $events = Get-WinEvent -FilterHashtable @{LogName='Application';ProviderName='MsiInstaller';StartTime=$since} -ErrorAction SilentlyContinue
        foreach ($e in $events) {
            $msg = [string]$e.Message
            if (-not $msg) { continue }
            $isFailure = ($e.Id -eq 11721) -or ($msg -match '(?i)(error\s+1721|错误\s*1721|status\s*[:=]\s*1603|错误状态\s*[:：]?\s*1603|\b1603\b|\b1618\b|\b1721\b)')
            if (-not $isFailure) { continue }
            if ($msg -notmatch '(?i)(ASUS|Armoury|ENE|HAL|Aac|Aura|Patriot|Holtek|VGA)') { continue }
            $flat = ($msg -replace '\s+',' ').Trim()
            if ($flat.Length -gt 280) { $flat = $flat.Substring(0,280) }
            $key = ([string]$e.Id) + '|' + $flat
            if ($seen.ContainsKey($key)) { continue }
            $seen[$key] = $true
            $out += [PSCustomObject]@{ObservedAt=$e.TimeCreated;Id=$e.Id;Message=$msg;Key=$key}
        }
    } catch {}
    return $out
}

function Get-LineObservedTime([string]$Line,[datetime]$Fallback) {
    $patterns = @(
        '(?<ts>\d{4}[-/]\d{1,2}[-/]\d{1,2}[ T]\d{1,2}:\d{2}:\d{2})',
        '(?<ts>\d{1,2}[-/]\d{1,2}[-/]\d{4}[ T]\d{1,2}:\d{2}:\d{2})'
    )
    foreach ($p in $patterns) {
        if ($Line -match $p) {
            $dt = [datetime]::MinValue
            if ([datetime]::TryParse($matches['ts'],[ref]$dt)) { return $dt }
        }
    }
    return $Fallback
}

function Get-ContextValue([string]$Context,[string[]]$Patterns) {
    foreach ($p in $Patterns) {
        try {
            if ($Context -match $p) {
                if ($matches.ContainsKey('v')) { return [string]$matches['v'] }
                if ($matches.Count -gt 1) { return [string]$matches[1] }
            }
        } catch {}
    }
    return ''
}

function Get-ArmouryErrorCode([string]$Line) {
    $patterns = @(
        '(?i)(?:UI\s*code|uicode|error\s*code)\s*[:=]\s*(?<v>4\d{3})',
        '(?i)Optional\s+Hal\s+(?<v>4\d{3})'
    )
    foreach ($p in $patterns) {
        if ($Line -match $p) { return [string]$matches['v'] }
    }
    if ($Line -match '(?i)FailedVersionMismatch') { return '4152' }
    return ''
}

function Get-ArmouryIncidentFromContext([string]$Line,[string]$Context,[datetime]$Observed,[string]$File) {
    $code = Get-ArmouryErrorCode $Line
    if (-not $code) { return $null }

    $profile = Get-ContextValue $Context @(
        '(?im)(?:ProfileID|Profile\s*ID)\s*[:=]\s*(?<v>\d{3,10})',
        '(?im)\bapid\s*[:=]\s*(?:AacSetup_)?(?<v>\d{3,10})'
    )
    $package = Get-ContextValue $Context @(
        '(?im)\bapn\s*[:=]\s*(?<v>[A-Za-z0-9_.+\- ]+)',
        '(?im)(?:Package|Component)\s*(?:Name)?\s*[:=]\s*(?<v>[A-Za-z0-9_.+\- ]+)'
    )
    $currentVersion = Get-ContextValue $Context @(
        '(?im)\bapcv\s*[:=]\s*(?<v>[0-9A-Za-z_.+\-]+)',
        '(?im)(?:current|installed)\s*(?:version)?\s*[:=]\s*(?<v>[0-9A-Za-z_.+\-]+)'
    )
    $targetVersion = Get-ContextValue $Context @(
        '(?im)\baptv\s*[:=]\s*(?<v>[0-9A-Za-z_.+\-]+)',
        '(?im)target\s*(?:version)?\s*[:=]\s*(?<v>[0-9A-Za-z_.+\-]+)'
    )
    $installerName = Get-ContextValue $Context @(
        '(?im)Install\s*filepath\s*[:=]\s*["'']?(?<v>[^\\/:*?"<>|\r\n]+?\.exe)',
        '(?im)\b(?<v>Aac[A-Za-z0-9_.+\-]+\.exe)\b'
    )
    $installerPath = Get-ContextValue $Context @(
        '(?im)(?:Install\s*filepath|CreateProcess(?:AsUserW)?(?:\s*path)?|FilePath)\s*[:=][^\r\n]*?["'']?(?<v>[A-Za-z]:\\[^\r\n"'']+?\.exe)',
        '(?im)["''](?<v>[A-Za-z]:\\[^\r\n"'']+?\.exe)["'']'
    )
    $exitCode = Get-ContextValue $Context @(
        '(?im)(?:Install\s*return\s*code|ExitCode)\s*[:=]\s*(?<v>-?\d+)'
    )

    $installer = [string]$installerName
    if ($installerPath) {
        try { $installer = [IO.Path]::GetFileName($installerPath) } catch {}
    }

    $matched = $null
    foreach ($d in $Known) {
        $stem = ([string]$d.Exe -replace '(?i)\.exe$','')
        if (($profile -and $profile -eq [string]$d.Profile) -or
            ($Context -match [regex]::Escape([string]$d.Profile)) -or
            ($Context -match [regex]::Escape([string]$d.Exe)) -or
            ($Context -match [regex]::Escape([string]$d.Name)) -or
            ($package -and $package -match [regex]::Escape($stem)) -or
            ($installer -and $installer -eq [string]$d.Exe)) {
            $matched = $d
            break
        }
    }

    $key = 'Unknown'
    $component = ''
    $group = 'DYNAMIC'
    $isKnown = $false
    if ($matched) {
        $key = [string]$matched.Key
        $component = [string]$matched.Name
        $group = [string]$matched.Group
        $isKnown = $true
    } else {
        if ($package) { $component = $package.Trim() }
        elseif ($installer) { $component = $installer }
        elseif ($profile) { $component = "Unknown HAL Profile $profile" }
        else { $component = 'Unknown Armoury HAL / Component' }

        if ($profile) { $key = "DynamicProfile_$profile" }
        elseif ($installer) { $key = "DynamicExe_$installer" }
        elseif ($package) { $key = "DynamicPackage_$($package.Trim())" }
    }

    return [PSCustomObject]@{
        ObservedAt=$Observed
        Code=$code
        Key=$key
        Profile=$profile
        Component=$component
        Package=$package
        Installer=$installer
        InstallerPath=$installerPath
        CurrentVersion=$currentVersion
        TargetVersion=$targetVersion
        ExitCode=$exitCode
        KnownComponent=$isKnown
        Group=$group
        File=$File
        Line=$Line.Trim()
        Context=$Context
    }
}

function Get-ArmouryErrorEvidence([int]$Minutes=180) {
    $hits = @()
    $seen = @{}
    $since = (Get-Date).AddMinutes(-1 * $Minutes)

    # v1.2.0 intentionally scans the broader ASUS log roots rather than only
    # today's known ROG Live Service subfolders. This keeps 4151/4152 detection
    # working if ASUS changes log layout in a future Armoury Crate release.
    $roots = @(
        "$env:ProgramData\ASUS",
        "$env:LOCALAPPDATA\ASUS"
    ) | Select-Object -Unique

    foreach ($root in $roots) {
        if (-not (Test-Path -LiteralPath $root)) { continue }
        try {
            $files = Get-ChildItem -LiteralPath $root -Recurse -File -ErrorAction SilentlyContinue |
                Where-Object {
                    $_.LastWriteTime -ge $since -and
                    $_.Length -lt 12MB -and
                    $_.Extension -match '^\.(log|txt)$'
                } |
                Sort-Object LastWriteTime -Descending |
                Select-Object -First 220

            foreach ($f in $files) {
                $lines = @()
                try { $lines = @(Get-Content -LiteralPath $f.FullName -Tail 6500 -ErrorAction Stop) }
                catch { continue }

                for ($i=0; $i -lt $lines.Count; $i++) {
                    $line = [string]$lines[$i]
                    if ($line -notmatch '(?i)(UI\s*code\s*[:=]\s*4\d{3}|uicode\s*[:=]\s*4\d{3}|error\s*code\s*[:=]\s*4\d{3}|Optional\s+Hal\s+4\d{3}|FailedVersionMismatch)') {
                        continue
                    }

                    $observed = Get-LineObservedTime $line $f.LastWriteTime
                    if ($observed -lt $since) { continue }

                    $lo = [Math]::Max(0,$i-32)
                    $hi = [Math]::Min($lines.Count-1,$i+32)
                    $context = ''
                    if ($hi -ge $lo) { $context = (@($lines[$lo..$hi]) -join "`n") }

                    $incident = Get-ArmouryIncidentFromContext $line $context $observed $f.FullName
                    if (-not $incident) { continue }

                    $bucketMinute = [int]([Math]::Floor($observed.Minute / 5) * 5)
                    $bucket = '{0:yyyyMMddHH}{1:00}' -f $observed,$bucketMinute
                    $identity = [string]$incident.Key
                    if (-not $identity -or $identity -eq 'Unknown') {
                        if ($incident.Profile) { $identity = "P$($incident.Profile)" }
                        elseif ($incident.Installer) { $identity = [string]$incident.Installer }
                        else { $identity = 'Unknown' }
                    }
                    $dedupKey = $identity + '|' + [string]$incident.Code + '|' + $bucket
                    if ($seen.ContainsKey($dedupKey)) { continue }
                    $seen[$dedupKey] = $true

                    $incident | Add-Member -NotePropertyName DedupKey -NotePropertyValue $dedupKey
                    $hits += $incident
                }
            }
        } catch {}
    }
    return @($hits | Sort-Object ObservedAt -Descending)
}

function Get-DynamicIncidentRows([object[]]$ActiveArmoury) {
    $out = @()
    $unknown = @($ActiveArmoury | Where-Object { -not $_.KnownComponent })
    if ($unknown.Count -eq 0) { return $out }

    $groups = @($unknown | Group-Object Key)
    foreach ($g in $groups) {
        $items = @($g.Group | Sort-Object ObservedAt -Descending)
        if ($items.Count -eq 0) { continue }
        $x = $items[0]

        $codes = @($items | Select-Object -ExpandProperty Code -Unique)
        $name = [string]$x.Component
        if (-not $name) { $name = 'Unknown Armoury HAL / Component' }
        if ($x.Profile) { $name = "$name [Profile $($x.Profile)]" }

        $detail = "动态检测到当前 Armoury 错误 $($codes -join ',')"
        if ($x.ExitCode) { $detail += "，安装返回码=$($x.ExitCode)" }
        $detail += '；属于未来版本/未知组件，已完整记录但不会自动卸载或修复。'

        $out += [PSCustomObject]@{
            Key=[string]$x.Key
            Name=$name
            Installed=[string]$x.CurrentVersion
            Target=[string]$x.TargetVersion
            Runtime=''
            ErrorCode=($codes -join ',')
            Status='MANUAL'
            Detail=$detail
            Group='DYNAMIC'
        }
    }
    return $out
}

function Get-RlsRecentInstallers([int]$Days=7,[int]$MaxItems=300) {
    $root = Join-Path $env:ProgramFiles 'ASUS\RLSDownload'
    $out = @()
    if (-not (Test-Path -LiteralPath $root)) { return $out }
    $since = (Get-Date).AddDays(-1 * $Days)

    try {
        $files = Get-ChildItem -LiteralPath $root -Recurse -File -ErrorAction SilentlyContinue |
            Where-Object {
                $_.LastWriteTime -ge $since -and
                $_.Extension -match '^\.(exe|msi)$'
            } |
            Sort-Object LastWriteTime -Descending |
            Select-Object -First $MaxItems

        foreach ($f in $files) {
            $fileVersion = ''
            $productVersion = ''
            try {
                $fileVersion = [string]$f.VersionInfo.FileVersion
                $productVersion = [string]$f.VersionInfo.ProductVersion
            } catch {}

            $profile = ''
            if ($f.FullName -match '(?i)\\4_HAL\\(?:AacSetup_)?(?<p>\d{4,10})\\') {
                $profile = [string]$matches['p']
            } elseif ($f.FullName -match '(?i)\\(?<p>\d{5})\\[^\\]+$') {
                $profile = [string]$matches['p']
            }

            $sigStatus = ''
            $signer = ''
            if ($f.Extension -ieq '.exe') {
                try {
                    $sig = Get-AuthenticodeSignature -FilePath $f.FullName -ErrorAction SilentlyContinue
                    if ($sig) {
                        $sigStatus = [string]$sig.Status
                        if ($sig.SignerCertificate) { $signer = [string]$sig.SignerCertificate.Subject }
                    }
                } catch {}
            }

            $out += [PSCustomObject]@{
                LastWriteTime=$f.LastWriteTime
                Profile=$profile
                Name=$f.Name
                FileVersion=$fileVersion
                ProductVersion=$productVersion
                Signature=$sigStatus
                Signer=$signer
                FullName=$f.FullName
            }
        }
    } catch {}
    return $out
}

function Get-PendingRepair {
    $items = @(
        [PSCustomObject]@{Key='PV';State='C:\ProgramData\ASUS4151TargetedFix\CurrentStatePath.txt';Module=$PVModule;Label='Patriot / VGA 4151'},
        [PSCustomObject]@{Key='HOLTEK';State='C:\ProgramData\ASUSCoreHAL4151Fix\CurrentStatePath.txt';Module=$HoltekModule;Label='Holtek Core HAL 4151'},
        [PSCustomObject]@{Key='ENE';State='C:\ProgramData\ASUS_ENE_M2_4152_Fix\CurrentStatePath.txt';Module=$ENEModule;Label='ENE M2 4152'}
    )
    foreach ($i in $items) {
        if (Test-Path -LiteralPath $i.State) { return $i }
    }
    return $null
}

function Get-DiagnosticRows([object[]]$ActiveArmoury=@()) {
    $rows = @()

    foreach ($d in $Known) {
        $installed = Get-InstalledVersion $d.ProductCode
        $target = Get-RlsTargetVersion $d
        $runtime = ''
        $status = 'INFO'
        $detail = ''
        $currentError = ''

        $incidents = @($ActiveArmoury | Where-Object { $_.Key -eq $d.Key })
        $latestIncident = $null
        if ($incidents.Count -gt 0) {
            $latestIncident = $incidents | Sort-Object ObservedAt -Descending | Select-Object -First 1
            $currentError = (@($incidents | Select-Object -ExpandProperty Code -Unique) -join ',')
            if (-not $target -and $latestIncident.TargetVersion) {
                $target = [string]$latestIncident.TargetVersion
            }
        }

        $hasActiveError = ($incidents.Count -gt 0)
        $expectedActive = $false
        if ($hasActiveError) {
            $expectedActive = (@($incidents | Where-Object { $_.Code -eq [string]$d.ExpectedCode }).Count -gt 0)
        }

        if ($d.Key -eq 'ENE') {
            $x64 = Get-FileVersionSafe 'C:\Program Files\ENE\Aac_ENE_EHD_M2_HAL\AacHal_x64.dll'
            $x86 = Get-FileVersionSafe 'C:\Program Files\ENE\Aac_ENE_EHD_M2_HAL\AacHal_x86.dll'
            $runtime = "x64=$x64; x86=$x86"

            $exactVerified4152 = (
                $hasActiveError -and
                $expectedActive -and
                $installed -eq $d.VerifiedGood -and
                $x64 -eq $d.VerifiedOld -and
                $x86 -eq $d.VerifiedOld -and
                ((-not $target) -or $target -eq $d.VerifiedGood)
            )

            if ($exactVerified4152) {
                $status = 'REPAIR'
                $detail = '命中已验证 4152 假成功：MSI 已升级，但两个实际 HAL DLL 仍为旧版'
            } elseif ($hasActiveError) {
                $status = 'MANUAL'
                if ($currentError -match '4152' -and $installed -and $x64 -and $x86 -and ($x64 -ne $installed -or $x86 -ne $installed)) {
                    $detail = "检测到当前 4152 且真实 DLL 与 MSI 不一致：MSI=$installed，$runtime；版本组合属于未来/未验证范围，仅诊断不自动修复"
                } else {
                    $detail = "检测到当前 Armoury 错误 $currentError；当前/目标版本属于未来或未验证组合，仅诊断不自动修复"
                }
            } elseif (-not $installed) {
                if ($target) {
                    $status = 'UPDATE'
                    $detail = "检测到 RLS 目标版本 $target，但当前 MSI 未注册；没有当前 4152，暂不自动操作"
                } else {
                    $status = 'N/A'
                    $detail = '本机未检测到该组件；不参与健康评分'
                }
            } elseif ($x64 -and $x86 -and ($x64 -ne $installed -or $x86 -ne $installed)) {
                $status = 'MANUAL'
                $detail = "没有新的 4152，但 MSI 与真实 DLL 版本不一致：MSI=$installed，$runtime；建议导出诊断报告"
            } elseif ($target -and (Compare-VersionSafe $target $installed) -gt 0) {
                $status = 'UPDATE'
                $detail = "存在正常新版本 $installed -> $target；当前未检测到 4152"
            } elseif ($x64 -eq $installed -and $x86 -eq $installed) {
                $status = 'PASS'
                $detail = 'MSI 与真实 DLL 一致；诊断不依赖固定目标版本'
            } else {
                $status = 'INFO'
                $detail = '版本状态可读取，但无法完成双 DLL 一致性确认'
            }
        } else {
            $exactVerifiedFault = (
                $hasActiveError -and
                $expectedActive -and
                $installed -eq $d.VerifiedOld -and
                $target -eq $d.VerifiedGood
            )

            if ($exactVerifiedFault) {
                $status = 'REPAIR'
                $detail = "命中已验证故障链 $installed -> $target，且当前日志出现 $($d.ExpectedCode)，可安全进入现有修复模块"
            } elseif ($hasActiveError) {
                $status = 'MANUAL'
                $observedCurrent = ''
                $observedTarget = ''
                if ($latestIncident) {
                    $observedCurrent = [string]$latestIncident.CurrentVersion
                    $observedTarget = [string]$latestIncident.TargetVersion
                }
                if (-not $observedCurrent) { $observedCurrent = $installed }
                if (-not $observedTarget) { $observedTarget = $target }
                $detail = "动态捕获当前错误 $currentError：current=$observedCurrent target=$observedTarget；属于未来/未验证版本组合，仅诊断不自动修复"
            } elseif (-not $installed) {
                if ($target) {
                    $status = 'UPDATE'
                    $detail = "发现 RLS 目标 $target，但没有当前 4151/4152 错误；不自动修复"
                } else {
                    $status = 'N/A'
                    $detail = '本机未检测到该组件；不参与健康评分'
                }
            } elseif ($target -and (Compare-VersionSafe $target $installed) -gt 0) {
                $status = 'UPDATE'
                $detail = "存在正常新版本 $installed -> $target；当前没有安装失败证据"
            } elseif ((Compare-VersionSafe $installed $d.VerifiedGood) -ge 0) {
                $status = 'PASS'
                $detail = '当前版本正常；未来更高版本同样按错误日志动态判断，不要求等于旧固定版本'
            } else {
                $status = 'INFO'
                $detail = '当前没有 4151/4152；版本低于历史验证基线，但不会仅因版本号自动修复'
            }
        }

        $rows += [PSCustomObject]@{
            Key=$d.Key
            Name=$d.Name
            Installed=$installed
            Target=$target
            Runtime=$runtime
            ErrorCode=$currentError
            Status=$status
            Detail=$detail
            Group=$d.Group
        }
    }

    # Unknown/new ASUS HAL profiles and future component names are appended dynamically.
    $rows += @(Get-DynamicIncidentRows $ActiveArmoury)
    return $rows
}

function Get-VersionDiff([object[]]$Rows) {
    if (-not (Test-Path -LiteralPath $BaselinePath)) { return @() }
    try {
        $b = Get-Content -LiteralPath $BaselinePath -Raw -ErrorAction Stop | ConvertFrom-Json
        $out = @()
        foreach ($old in @($b.Rows)) {
            $now = $Rows | Where-Object { $_.Key -eq $old.Key } | Select-Object -First 1
            if (-not $now) { continue }
            $parts = @()
            if ([string]$old.Installed -ne [string]$now.Installed) {
                $parts += ("MSI {0} -> {1}" -f [string]$old.Installed,[string]$now.Installed)
            }
            if ([string]$old.Runtime -ne [string]$now.Runtime -and ([string]$old.Runtime -or [string]$now.Runtime)) {
                $parts += ("Runtime {0} -> {1}" -f [string]$old.Runtime,[string]$now.Runtime)
            }
            if ($parts.Count -gt 0) {
                $out += ("{0}: {1}" -f [string]$now.Name,($parts -join '; '))
            }
        }
        return $out
    } catch {
        return @()
    }
}

function Save-RepairBaseline([string]$Group,[object[]]$Rows) {
    try {
        $obj = [PSCustomObject]@{
            Version=$AppVersion
            Group=$Group
            Created=(Get-Date).ToString('o')
            Rows=@($Rows | Select-Object Key,Name,Installed,Target,Runtime,Status)
        }
        $obj | ConvertTo-Json -Depth 5 | Set-Content -LiteralPath $BaselinePath -Encoding UTF8
    } catch {}
}

function Get-RecommendedRepairGroup([object[]]$Rows,[object[]]$ActiveArmoury) {
    $repairRows = @($Rows | Where-Object { $_.Status -eq 'REPAIR' })
    if ($repairRows.Count -eq 0) { return $null }
    $activeKeys = @($ActiveArmoury | Select-Object -ExpandProperty Key -Unique)
    foreach ($group in @('PV','HOLTEK','ENE')) {
        $candidates = @($repairRows | Where-Object { $_.Group -eq $group })
        if ($candidates.Count -eq 0) { continue }
        foreach ($c in $candidates) {
            if ($activeKeys -contains $c.Key) { return $group }
        }
    }
    foreach ($group in @('PV','HOLTEK','ENE')) {
        if (@($repairRows | Where-Object { $_.Group -eq $group }).Count -gt 0) { return $group }
    }
    return $null
}

function Get-SystemSnapshot([switch]$Force) {
    $now = Get-Date
    if (-not $Force -and $script:SnapshotCache -and (($now - $script:SnapshotCacheTime).TotalSeconds -lt 15)) {
        return $script:SnapshotCache
    }

    $activeWindow = 15
    $historyWindow = 180
    $armAll = @(Get-ArmouryErrorEvidence $historyWindow)
    Save-IncidentHistory $armAll
    $msiAll = @(Get-RecentMsiErrors $historyWindow)
    $cut = $now.AddMinutes(-1 * $activeWindow)
    $activeArmoury = @($armAll | Where-Object { $_.ObservedAt -ge $cut })
    $historyArmoury = @($armAll | Where-Object { $_.ObservedAt -lt $cut })
    $activeMsi = @($msiAll | Where-Object { $_.ObservedAt -ge $cut })
    $historyMsi = @($msiAll | Where-Object { $_.ObservedAt -lt $cut })
    # Correlation is computed only after the active windows are materialized.
    # Scores group evidence for display/incident management only; they never grant repair permission.
    $correlated = @(Get-CorrelatedIncidents $activeArmoury $activeMsi)
    $rows = @(Get-DiagnosticRows $activeArmoury)
    $rows += @(Get-RuntimeDiagnosticRows)
    $pending = Get-PendingRepair
    $repair = @($rows | Where-Object { $_.Status -eq 'REPAIR' })
    $runtimeUpdate = @($rows | Where-Object { $_.Group -eq 'RUNTIME' -and $_.Status -eq 'UPDATE' })
    $manual = @($rows | Where-Object { $_.Status -eq 'MANUAL' })

    $health = 'HEALTHY'
    $healthText = '健康'
    if ($pending) {
        $health = 'WAIT_REBOOT'
        $healthText = '等待重启 / 续跑'
    } elseif ($repair.Count -gt 0 -or $runtimeUpdate.Count -gt 0) {
        $health = 'NEEDS_REPAIR'
        if ($repair.Count -gt 0) { $healthText = '需要修复' } else { $healthText = '系统运行库可更新' }
    } elseif ($manual.Count -gt 0 -or @($activeArmoury).Count -gt 0) {
        $health = 'MANUAL'
        $healthText = '检测到故障 / 需要人工确认'
    }

    $recommended = Get-RecommendedRepairGroup $rows $activeArmoury
    $diff = @(Get-VersionDiff $rows)
    $codes = @($activeArmoury | Select-Object -ExpandProperty Code -Unique | Sort-Object)

    $obj = [PSCustomObject]@{
        CapturedAt=$now
        Rows=$rows
        Pending=$pending
        ActiveArmoury=$activeArmoury
        HistoryArmoury=$historyArmoury
        ActiveMsi=$activeMsi
        HistoryMsi=$historyMsi
        ActiveErrorCodes=$codes
        CorrelatedIncidents=$correlated
        Health=$health
        HealthText=$healthText
        RecommendedGroup=$recommended
        VersionDiff=$diff
        PendingReboot=@(Get-PendingRebootReasons)
    }
    $script:SnapshotCache = $obj
    $script:SnapshotCacheTime = $now
    return $obj
}

function Get-BuildConsistency {
    $rows=@();function AddC([string]$Item,[string]$Status,[string]$Expected,[string]$Actual,[string]$Detail=''){$script:__bc += [PSCustomObject]@{Item=$Item;Status=$Status;Expected=$Expected;Actual=$Actual;Detail=$Detail}};$script:__bc=@()
    try{$a=(Get-FileHash -Algorithm SHA256 -LiteralPath $PSCommandPath).Hash.ToLowerInvariant();AddC 'Engine SHA256' $(if($a -eq [string]$BuildInfo.EngineSHA256){'PASS'}else{'FAIL'}) ([string]$BuildInfo.EngineSHA256) $a ''}catch{AddC 'Engine SHA256' 'FAIL' ([string]$BuildInfo.EngineSHA256) '' $_.Exception.Message}
    try{$a=(Get-FileHash -Algorithm SHA256 -LiteralPath $BrokerPath).Hash.ToLowerInvariant();AddC 'Broker SHA256' $(if($a -eq [string]$BuildInfo.BrokerSHA256){'PASS'}else{'FAIL'}) ([string]$BuildInfo.BrokerSHA256) $a ''}catch{AddC 'Broker SHA256' 'FAIL' ([string]$BuildInfo.BrokerSHA256) '' $_.Exception.Message}
    $bp=Join-Path $PSScriptRoot 'Bootstrap.ps1';try{$a=(Get-FileHash -Algorithm SHA256 -LiteralPath $bp).Hash.ToLowerInvariant();AddC 'Bootstrap SHA256' $(if($a -eq [string]$BuildInfo.BootstrapSHA256){'PASS'}else{'FAIL'}) ([string]$BuildInfo.BootstrapSHA256) $a ''}catch{AddC 'Bootstrap SHA256' 'FAIL' ([string]$BuildInfo.BootstrapSHA256) '' $_.Exception.Message}
    AddC 'Engine Version' $(if($AppVersion -eq [string]$BuildInfo.Version){'PASS'}else{'FAIL'}) ([string]$BuildInfo.Version) $AppVersion '';AddC 'Build ID' $(if($BuildId -eq [string]$BuildInfo.BuildId){'PASS'}else{'FAIL'}) ([string]$BuildInfo.BuildId) $BuildId ''
    if($script:CurrentPlan){$ok=([string]$script:CurrentPlan.AppVersion -eq $AppVersion -and [string]$script:CurrentPlan.BuildId -eq $BuildId);AddC 'Current Plan Build' $(if($ok){'PASS'}else{'WARN'}) "$AppVersion/$BuildId" "$($script:CurrentPlan.AppVersion)/$($script:CurrentPlan.BuildId)" $(if($ok){''}else{'当前 Dry Run 来自旧 Engine；应重新生成计划'})}
    $legacy=Join-Path $LegacyWorkRoot 'RepairCenter.ps1';if(Test-Path -LiteralPath $legacy){AddC 'Legacy ProgramData Runtime' 'INFO' 'not used by current v2.3.2' $legacy '检测到旧版 ProgramData 运行文件；当前 Engine 使用 LocalAppData，不会调用旧文件'}
    $rows=@($script:__bc);Remove-Variable __bc -Scope Script -ErrorAction SilentlyContinue;$fatal=@($rows|Where-Object{$_.Status -eq 'FAIL'});return [PSCustomObject]@{Status=$(if($fatal.Count -eq 0){'PASS'}else{'BUILD_MISMATCH'});Rows=$rows;EngineVersion=$AppVersion;BuildId=$BuildId;EngineSHA256=$script:EngineSHA256;BuildInfoSHA256=$script:BuildInfoSHA256}
}
function Write-ReportIntegrityManifest([string]$ReportRoot){$files=@();foreach($f in @(Get-ChildItem -LiteralPath $ReportRoot -Recurse -File -ErrorAction SilentlyContinue|Where-Object{$_.Name -notin @('report_manifest.json','report_manifest.sha256')}|Sort-Object FullName)){try{$rel=$f.FullName.Substring($ReportRoot.Length).TrimStart('\');$files += [PSCustomObject]@{Path=$rel;Bytes=[int64]$f.Length;SHA256=(Get-FileHash -Algorithm SHA256 -LiteralPath $f.FullName).Hash.ToLowerInvariant()}}catch{}};$bc=Get-BuildConsistency;$m=[PSCustomObject]@{SchemaVersion=2;Product=[string]$BuildInfo.Product;Version=$AppVersion;BuildId=$BuildId;GeneratedAt=(Get-Date).ToString('o');EngineSHA256=$script:EngineSHA256;BrokerSHA256=[string]$BuildInfo.BrokerSHA256;BuildConsistency=$bc.Status;FileCount=$files.Count;Files=$files};$mp=Join-Path $ReportRoot 'report_manifest.json';[void](Write-JsonAtomic $mp $m 16);$mh=(Get-FileHash -Algorithm SHA256 -LiteralPath $mp).Hash.ToLowerInvariant();$mh|Set-Content -LiteralPath (Join-Path $ReportRoot 'report_manifest.sha256') -Encoding ASCII;return $m}

function New-ReportFolder([string]$Prefix) {
    $p = Join-Path $Desktop ($Prefix + '_' + (Get-Date -Format 'yyyyMMdd_HHmmss'))
    New-Item -ItemType Directory -Force -Path $p | Out-Null
    return $p
}

function Export-DiagnosticReport {
    $snap = Get-SystemSnapshot -Force
    try{[void](Invoke-GamePlatformDeepTest)}catch{}
    $consistency=Get-BuildConsistency
    $out = New-ReportFolder 'GameRuntime_ASUS_SelfHealing_Report'
    $snap.Rows | Format-Table -AutoSize | Out-String -Width 600 | Set-Content (Join-Path $out 'Component_Status.txt') -Encoding UTF8

    @(
        "Windows Game Runtime / ASUS Self-Healing Center v$AppVersion",
        "BuildId=$BuildId",
        "ReportSchema=$ReportSchemaVersion",
        "EngineSHA256=$script:EngineSHA256",
        "BrokerSHA256=$ExpectedBrokerSHA256",
        "BuildConsistency=$($consistency.Status)",
        "CapturedAt=$($snap.CapturedAt)",
        "Health=$($snap.HealthText)",
        "RecommendedGroup=$($snap.RecommendedGroup)",
        "ActiveArmoury=$(@($snap.ActiveArmoury).Count)",
        "ActiveMSI=$(@($snap.ActiveMsi).Count)",
        "ActiveErrorCodes=$(@($snap.ActiveErrorCodes) -join ',')",
        "HistoryArmoury3h=$(@($snap.HistoryArmoury).Count)",
        "HistoryMSI3h=$(@($snap.HistoryMsi).Count)",
        "PendingReboot=$(@($snap.PendingReboot) -join ',')",
        "VersionDiff=$(@($snap.VersionDiff) -join ' | ')"
    ) | Set-Content (Join-Path $out 'Health_Summary.txt') -Encoding UTF8

    @($snap.ActiveArmoury) | Select-Object ObservedAt,Code,Key,Profile,Component,Package,Installer,CurrentVersion,TargetVersion,ExitCode,KnownComponent,File,Line |
        Format-List | Out-String -Width 900 | Set-Content (Join-Path $out 'Armoury_Active_15min.txt') -Encoding UTF8
    @($snap.HistoryArmoury) | Select-Object ObservedAt,Code,Key,Profile,Component,Package,Installer,CurrentVersion,TargetVersion,ExitCode,KnownComponent,File,Line |
        Format-List | Out-String -Width 900 | Set-Content (Join-Path $out 'Armoury_History_3h.txt') -Encoding UTF8

    @($snap.CorrelatedIncidents) | Format-Table -AutoSize | Out-String -Width 1000 | Set-Content (Join-Path $out 'Correlated_Incidents.txt') -Encoding UTF8

    @($snap.ActiveArmoury | Where-Object { -not $_.KnownComponent }) |
        Select-Object ObservedAt,Code,Profile,Component,Package,Installer,InstallerPath,CurrentVersion,TargetVersion,ExitCode,File |
        Format-List | Out-String -Width 900 |
        Set-Content (Join-Path $out 'Dynamic_Unknown_or_Future_Incidents.txt') -Encoding UTF8

    @(Get-RlsRecentInstallers -Days 7 -MaxItems 350) |
        Format-Table -AutoSize | Out-String -Width 1000 |
        Set-Content (Join-Path $out 'RLS_Recent_Installers_7days.txt') -Encoding UTF8
    @($snap.ActiveMsi) | Select-Object ObservedAt,Id,Message | Format-List | Out-String -Width 700 | Set-Content (Join-Path $out 'MSI_Active_15min.txt') -Encoding UTF8
    @($snap.HistoryMsi) | Select-Object ObservedAt,Id,Message | Format-List | Out-String -Width 700 | Set-Content (Join-Path $out 'MSI_History_3h.txt') -Encoding UTF8

    Get-Service -ErrorAction SilentlyContinue |
        Where-Object { $_.Name -match 'ASUS|Armoury|ROG|Aura|Lighting|ENE|Aac' } |
        Sort-Object Name | Format-Table -AutoSize | Out-String -Width 500 |
        Set-Content (Join-Path $out 'ASUS_Services.txt') -Encoding UTF8

    @($snap.PendingReboot) | Set-Content (Join-Path $out 'PendingReboot.txt') -Encoding UTF8
    @(Get-PendingFileRenameDetails)|Format-Table -AutoSize|Out-String -Width 1400|Set-Content (Join-Path $out 'PendingFileRenameOperations_Details.txt') -Encoding UTF8
    $installerState=Get-InstallerBusyState;@($installerState.All)|Format-Table -AutoSize|Out-String -Width 1600|Set-Content (Join-Path $out 'WindowsInstaller_Process_Details.txt') -Encoding UTF8

    $pf=Get-EnvironmentPreflight 'Report'
    @($pf.Rows) | Format-Table -AutoSize | Out-String -Width 900 |
        Set-Content (Join-Path $out 'Safety_Preflight.txt') -Encoding UTF8
    @(Get-RecentTransactions 50) | Select-Object TransactionId,Type,Group,Label,State,StartedAt,UpdatedAt,LastDetail |
        Format-Table -AutoSize | Out-String -Width 1200 |
        Set-Content (Join-Path $out 'Repair_Transactions.txt') -Encoding UTF8
    if($script:CurrentPlan){
        (Format-RepairPlan $script:CurrentPlan) | Set-Content (Join-Path $out 'Current_DryRun_Plan.txt') -Encoding UTF8
    }
    if(Test-Path -LiteralPath $IncidentDbPath){
        Get-Content -LiteralPath $IncidentDbPath -Tail 4000 -ErrorAction SilentlyContinue |
            Set-Content (Join-Path $out 'IncidentHistory_tail.jsonl') -Encoding UTF8
    }
    if(Test-Path -LiteralPath $DeepTestLastPath){
        Copy-Item -LiteralPath $DeepTestLastPath -Destination (Join-Path $out 'Last_GameRuntime_DeepTest.json') -Force -ErrorAction SilentlyContinue
    }

    try{@(Get-GPUHealthRows)|Format-Table -AutoSize|Out-String -Width 1200|Set-Content (Join-Path $out 'GPU_Health.txt') -Encoding UTF8}catch{}
    try{@(Get-GameCrashTelemetry 7 250 -Raw)|Format-List|Out-String -Width 1400|Set-Content (Join-Path $out 'Game_Crash_Telemetry_7days.txt') -Encoding UTF8}catch{}
    try{@(Get-AdditionalGameRuntimeRows)|Format-Table -AutoSize|Out-String -Width 1200|Set-Content (Join-Path $out 'Additional_Game_Runtimes.txt') -Encoding UTF8}catch{}
    try{@(Get-WerLocalDumpStatus)|Format-Table -AutoSize|Out-String -Width 1000|Set-Content (Join-Path $out 'WER_LocalDumps.txt') -Encoding UTF8}catch{}
    try{@(Get-RulePackStatus)|Format-List|Out-String -Width 1200|Set-Content (Join-Path $out 'RulePack_Trust.txt') -Encoding UTF8}catch{}
    try{Get-ArchitectureSecuritySummary|Format-List|Out-String -Width 1200|Set-Content (Join-Path $out 'Broker_Policy_Architecture.txt') -Encoding UTF8}catch{}
    $newDeep=Join-Path $DeepTestRoot 'LastGamePlatformDeepTest.json';if(Test-Path -LiteralPath $newDeep){Copy-Item -LiteralPath $newDeep -Destination (Join-Path $out 'Last_GamePlatform_DeepTest.json') -Force -ErrorAction SilentlyContinue}


    @(Get-RuntimeDiagnosticRows) | Format-Table -AutoSize | Out-String -Width 900 |
        Set-Content (Join-Path $out 'VCpp_DirectX_Status.txt') -Encoding UTF8
    @(Get-VCRuntimeErrorEvidence 168) | Format-List | Out-String -Width 900 |
        Set-Content (Join-Path $out 'VCpp_Runtime_Error_Evidence_7days.txt') -Encoding UTF8
    @(Get-LegacyVCRedistInventory) | Format-Table -AutoSize | Out-String -Width 900 |
        Set-Content (Join-Path $out 'VCpp_Legacy_2005_2013_Inventory.txt') -Encoding UTF8
    try {
        $dxp = Invoke-DxDiagCapture
        if ($dxp -and (Test-Path -LiteralPath $dxp)) { Copy-Item -LiteralPath $dxp -Destination (Join-Path $out 'DxDiag.txt') -Force }
    } catch {}
    if ($script:RuntimeOnlineInfo) {
        $script:RuntimeOnlineInfo.GetEnumerator() | ForEach-Object {
            [PSCustomObject]@{Key=$_.Key;Success=$_.Value.Success;TrustComplete=$_.Value.TrustComplete;Version=$_.Value.Version;Path=$_.Value.Path;SHA256=$_.Value.SHA256;SignatureStatus=$_.Value.SignatureStatus;Signer=$_.Value.Signer;Thumbprint=$_.Value.Thumbprint;Issuer=$_.Value.Issuer;Source=$_.Value.Source;OriginalUri=$_.Value.OriginalUri;FinalUri=$_.Value.FinalUri;FinalHost=$_.Value.FinalHost;VerifiedAt=$_.Value.VerifiedAt;Error=$_.Value.Error}
        } | Format-Table -AutoSize | Out-String -Width 1000 |
            Set-Content (Join-Path $out 'Runtime_Online_Microsoft_Packages.txt') -Encoding UTF8
    }

    try{@(Get-PnpRelatedInventory)|Format-Table Status,Severity,Class,FriendlyName,ProblemCode,ProblemText,InstanceId -AutoSize|Out-String -Width 1800|Set-Content (Join-Path $out 'PnP_Related.txt') -Encoding UTF8}catch{}

    @($consistency.Rows)|Format-Table -AutoSize|Out-String -Width 1600|Set-Content (Join-Path $out 'Build_SelfConsistency.txt') -Encoding UTF8
    $logdir = Join-Path $out 'Recent_ASUS_Logs'
    New-Item -ItemType Directory -Force -Path $logdir | Out-Null
    foreach ($root in @("$env:ProgramData\ASUS","$env:LOCALAPPDATA\ASUS")) {
        if (-not (Test-Path -LiteralPath $root)) { continue }
        try {
            Get-ChildItem -LiteralPath $root -Recurse -File -ErrorAction SilentlyContinue |
                Where-Object { $_.LastWriteTime -gt (Get-Date).AddDays(-3) -and $_.Length -lt 5MB -and $_.Extension -match '^\.(log|txt|json|xml)$' } |
                Sort-Object LastWriteTime -Descending | Select-Object -First 250 | ForEach-Object {
                    $name = ($_.FullName -replace '[:\\/ ]','_')
                    Copy-Item -LiteralPath $_.FullName -Destination (Join-Path $logdir $name) -Force -ErrorAction SilentlyContinue
                }
        } catch {}
    }

    if (Test-Path -LiteralPath $LauncherLog) {
        Copy-Item -LiteralPath $LauncherLog -Destination (Join-Path $out 'Launcher.log') -Force -ErrorAction SilentlyContinue
    }

    [void](Write-ReportIntegrityManifest $out)
    $zip = "$out.zip"
    try { Compress-Archive -Path "$out\*" -DestinationPath $zip -Force -ErrorAction Stop }
    catch { return $out }
    return $zip
}

function Get-ModuleInfo([string]$Group) {
    switch ($Group) {
        'PV' { return [PSCustomObject]@{Module=$PVModule;Pattern='ASUS_4151_TargetedFix_*';Label='Patriot / VGA 4151'} }
        'HOLTEK' { return [PSCustomObject]@{Module=$HoltekModule;Pattern='ASUS_CoreHAL_4151_Fix_*';Label='Holtek Core HAL 4151'} }
        'ENE' { return [PSCustomObject]@{Module=$ENEModule;Pattern='ASUS_ENE_M2_4152_Fix_*';Label='ENE M2 HAL 4152'} }
    }
    return $null
}

function Invoke-ModuleProcess([string]$Module,[string]$Phase) {
    $psExe = Join-Path $env:WINDIR 'System32\WindowsPowerShell\v1.0\powershell.exe'
    $arg = "-NoProfile -ExecutionPolicy Bypass -File `"$Module`" -Phase $Phase"
    try {
        $p = Start-Process -FilePath $psExe -ArgumentList $arg -PassThru
        return (Wait-ProcessResponsive $p)
    } catch {
        return 99999
    }
}

function Find-LatestSelfTestStatus([string]$Pattern,[datetime]$After) {
    $dirs = Get-ChildItem $Desktop -Directory -Filter $Pattern -ErrorAction SilentlyContinue |
        Where-Object { $_.LastWriteTime -ge $After.AddSeconds(-2) } | Sort-Object LastWriteTime -Descending
    foreach ($d in $dirs) {
        $p = Join-Path $d.FullName 'SELFTEST_STATUS.txt'
        if (Test-Path -LiteralPath $p) {
            return [PSCustomObject]@{Status=(Get-Content -LiteralPath $p -Raw).Trim();Dir=$d.FullName}
        }
    }
    return $null
}

function Invoke-SafeRepairGroup([string]$Group,[object[]]$Rows) {
    $script:SnapshotCacheTime=[datetime]::MinValue
    $snap=Get-SystemSnapshot -Force
    $plan=New-RepairPlan 'ASUS' $Group $snap
    if(-not $plan.Eligible){
        [System.Windows.Forms.MessageBox]::Show((Format-RepairPlan $plan),'修复预演未通过',[System.Windows.Forms.MessageBoxButtons]::OK,[System.Windows.Forms.MessageBoxIcon]::Warning)|Out-Null
        return
    }
    $ans=[System.Windows.Forms.MessageBox]::Show((Format-RepairPlan $plan)+"`r`n`r`n这是 Dry Run 预演结果。确认创建正式事务并先执行 SelfTest？",'修复预演 / 事务确认',[System.Windows.Forms.MessageBoxButtons]::YesNo,[System.Windows.Forms.MessageBoxIcon]::Question)
    if($ans -ne [System.Windows.Forms.DialogResult]::Yes){return}

    $tx=New-RepairTransaction $plan $snap
    Set-TransactionState $tx 'SelfTestStarted' '开始只读 SelfTest；事务 Evidence Bundle 已落盘'
    $info=Get-ModuleInfo $Group
    Save-RepairBaseline $Group $Rows
    $t=Get-Date
    [void](Invoke-ModuleProcess $info.Module 'SelfTest')
    $st=Find-LatestSelfTestStatus $info.Pattern $t
    if(-not $st -or $st.Status -ne 'PASS'){
        Set-TransactionState $tx 'Failed' 'SelfTest 未通过；正式修复未启动'
        [System.Windows.Forms.MessageBox]::Show('SelfTest 未通过。事务已安全停止，没有进入正式卸载/安装。','安全门禁',[System.Windows.Forms.MessageBoxButtons]::OK,[System.Windows.Forms.MessageBoxIcon]::Warning)|Out-Null
        return
    }
    Set-TransactionState $tx 'SelfTestPassed' ("SelfTest PASS: "+$st.Dir)
    $ans2=[System.Windows.Forms.MessageBox]::Show("SelfTest PASS。`r`n事务：$($tx.TransactionId)`r`n`r`n是否执行正式修复？",'最终执行确认',[System.Windows.Forms.MessageBoxButtons]::YesNo,[System.Windows.Forms.MessageBoxIcon]::Question)
    if($ans2 -ne [System.Windows.Forms.DialogResult]::Yes){Set-TransactionState $tx 'Cancelled' '用户在正式执行前取消';return}
    Set-TransactionState $tx 'RepairStarted' '即将调用精确哈希锁定的已验证修复模块 Start'
    Set-TransactionState $tx 'ModuleExecuting' '底层模块开始执行；中断后将读取模块 state.json 决定续跑/停止'
    $script:RepairExecutionActive=$true
    try{[void](Invoke-ModuleProcess $info.Module 'Start')}finally{$script:RepairExecutionActive=$false}
    $pending=Get-PendingRepair
    if($pending){Set-TransactionState $tx 'AwaitingReboot' '修复模块阶段1完成/存在待续跑状态'}
    else{
        $fx=Find-LatestFixStatus $info.Pattern $t
        if($fx -and $fx.Status -eq 'SUCCESS'){Set-TransactionState $tx 'SuccessPendingVerification' ("模块 SUCCESS: "+$fx.Dir)}
        elseif($fx -and $fx.Status -match '^FAILED'){Set-TransactionState $tx 'NeedsAttention' ("模块状态 "+$fx.Status)}
        else{Set-TransactionState $tx 'NeedsVerification' '修复模块已返回，等待最终验收'}
    }
    $script:SnapshotCacheTime=[datetime]::MinValue
}

function Continue-PendingRepair {
    $p=Get-PendingRepair
    $tx=Sync-OpenTransactionState
    if(-not $p){
        if($tx -and $tx.State -eq 'SuccessPendingVerification'){
            [System.Windows.Forms.MessageBox]::Show('底层修复模块已经完成，当前只需要执行「最终验收」。','事务状态')|Out-Null
        } else {
            [System.Windows.Forms.MessageBox]::Show('没有检测到需要 PostReboot 续跑的修复状态。')|Out-Null
        }
        return
    }
    if($tx -and $tx.State -eq 'AwaitingReboot' -and $tx.BootTimeBefore){
        $bootNow=Get-BootTimeText
        if($bootNow -and [string]$bootNow -eq [string]$tx.BootTimeBefore){
            [System.Windows.Forms.MessageBox]::Show("事务 $($tx.TransactionId) 仍处于同一次 Windows 启动会话。`r`n`r`nBootTime=$bootNow`r`n`r`n必须真正重启 Windows 后才能执行 PostReboot；中央事务门禁已阻止续跑。",'真实重启门禁',[System.Windows.Forms.MessageBoxButtons]::OK,[System.Windows.Forms.MessageBoxIcon]::Warning)|Out-Null
            return
        }
    }
    $ans=[System.Windows.Forms.MessageBox]::Show("检测到未完成修复：$($p.Label)。`r`n将尝试 PostReboot 续跑。中央事务层和底层模块都会验证真实重启。",'继续修复',[System.Windows.Forms.MessageBoxButtons]::YesNo,[System.Windows.Forms.MessageBoxIcon]::Question)
    if($ans -eq [System.Windows.Forms.DialogResult]::Yes){
        if($tx){Set-TransactionState $tx 'PostRebootStarted' '调用 PostReboot 续跑'}
        $script:RepairExecutionActive=$true
        try{[void](Invoke-ModuleProcess $p.Module 'PostReboot')}finally{$script:RepairExecutionActive=$false}
        $script:SnapshotCacheTime=[datetime]::MinValue
        if($tx){
            $info=Get-ModuleInfo ([string]$tx.Group);$st=[datetime]::MinValue;try{$st=[datetime]$tx.StartedAt}catch{}
            $fx=Find-LatestFixStatus $info.Pattern $st
            if($fx -and $fx.Status -eq 'SUCCESS'){Set-TransactionState $tx 'SuccessPendingVerification' ("PostReboot SUCCESS: "+$fx.Dir)}
            elseif($fx -and $fx.Status -match '^FAILED'){Set-TransactionState $tx 'NeedsAttention' ("PostReboot "+$fx.Status)}
            else{Set-TransactionState $tx 'NeedsVerification' 'PostReboot 已返回，等待最终验收'}
        }
    }
}

function Run-FinalVerification {
    $script:SnapshotCacheTime = [datetime]::MinValue
    $snap = Get-SystemSnapshot -Force
    $out = Join-Path $Desktop ('GameRuntime_ASUS_Final_Verification_' + (Get-Date -Format 'yyyyMMdd_HHmmss') + '.txt')
    $lines = New-Object System.Collections.ArrayList
    $counts = @{PASS=0;WARN=0;FAIL=0}
    function AddV([string]$Kind,[string]$Text) {
        $label = @{PASS='正常';WARN='需关注';FAIL='需处理'}[$Kind]
        [void]$lines.Add("[$label] $Text")
        $counts[$Kind] = [int]$counts[$Kind] + 1
    }

    foreach ($r in @($snap.Rows)) {
        $answer = [string]$r.Detail
        if (-not $answer) { $answer = [string]$r.Runtime }
        if (-not $answer) { $answer = '本机可用' }
        if ($r.Status -eq 'PASS' -or $r.Status -in @('N/A','INFO')) { AddV 'PASS' "$($r.Name)  $answer" }
        elseif ($r.Status -eq 'REPAIR') { AddV 'FAIL' "$($r.Name)  $answer" }
        elseif ($r.Status -eq 'UPDATE') { AddV 'WARN' "$($r.Name)  有可用更新" }
        else { AddV 'WARN' "$($r.Name)  $answer" }
    }

    $svcMap = @{ArmouryCrateService='奥创主服务';'ROG Live Service'='ROG 在线服务';LightingService='灯效服务'}
    foreach ($n in @('ArmouryCrateService','ROG Live Service','LightingService')) {
        $svc = Get-Service -Name $n -ErrorAction SilentlyContinue
        $label = $svcMap[$n]
        if ($svc -and $svc.Status -eq 'Running') { AddV 'PASS' "$label正在运行" }
        else { AddV 'WARN' "$label未运行" }
    }

    if (@($snap.ActiveMsi).Count -eq 0) { AddV 'PASS' '最近没有安装失败记录' }
    else { AddV 'WARN' '最近有安装失败记录，建议到奥创中心查看' }

    if (@($snap.ActiveArmoury).Count -eq 0) {
        AddV 'PASS' '最近没有奥创更新错误'
    } else {
        AddV 'FAIL' '最近仍有奥创更新错误，请到奥创中心处理'
    }

    if (@($snap.PendingReboot).Count -eq 0) { AddV 'PASS' '不需要重启' }
    else { AddV 'WARN' '需要先重启电脑，再回来检测' }

    $overall = if($counts.FAIL -gt 0){'需要处理'}elseif($counts.WARN -gt 0){'有项目需要关注'}else{'全部正常'}
    $header = @(
        '=== 自愈中心 检测结果 ===',
        ('时间: ' + (Get-Date)),
        ('版本: ' + $AppVersion),
        ('总体状态: ' + $snap.HealthText),
        ''
    )
    $summary = "小结：正常={0}  需关注={1}  需处理={2}  → {3}" -f $counts.PASS,$counts.WARN,$counts.FAIL,$overall
    ($header + @($lines) + @('', $summary)) | Set-Content -LiteralPath $out -Encoding Unicode

    $icon = [System.Windows.Forms.MessageBoxIcon]::Information
    if ($counts.FAIL -gt 0) { $icon = [System.Windows.Forms.MessageBoxIcon]::Warning }
    [System.Windows.Forms.MessageBox]::Show(("检测完成：{0}`r`n当前状态：{1}`r`n结果已保存到报告中心。" -f $overall,$snap.HealthText),'检测结果',[System.Windows.Forms.MessageBoxButtons]::OK,$icon) | Out-Null
    $tx=Sync-OpenTransactionState
    if($tx -and $tx.State -notin @('Completed','Failed','NeedsAttention','Cancelled','Observing')){
        $v=Get-StrictTransactionVerification $tx
        if($v.Success){
            Save-TransactionEvidenceAfter $tx $v.Snapshot
            if(Start-TransactionObservation $tx 60){
                [System.Windows.Forms.MessageBox]::Show('修复后观察已开始，大约一分钟。完成后这里会自动更新结果。','观察中',[System.Windows.Forms.MessageBoxButtons]::OK,[System.Windows.Forms.MessageBoxIcon]::Information)|Out-Null
            }
        }else{Set-TransactionState $tx 'NeedsAttention' ("严格最终验收未通过："+(@($v.Reasons)-join ' | '))}
    } elseif($tx -and $tx.State -eq 'Observing'){
        [System.Windows.Forms.MessageBox]::Show('正在观察修复结果，请稍等。','观察中')|Out-Null
    }
    return $out
}


# ---------- v2.3 broker, rule-pack, policy, crash/GPU/runtime diagnostics ----------
function Test-BrokerIntegrity {
    if (-not (Test-Path -LiteralPath $BrokerPath)) { return [PSCustomObject]@{Valid=$false;Detail='Broker file missing';SHA256=''} }
    try {
        $h=(Get-FileHash -Algorithm SHA256 -LiteralPath $BrokerPath -ErrorAction Stop).Hash.ToLowerInvariant()
        return [PSCustomObject]@{Valid=($h -eq $ExpectedBrokerSHA256);Detail=$(if($h -eq $ExpectedBrokerSHA256){'Broker SHA256 matches engine-pinned value'}else{"Broker SHA256 mismatch: $h"});SHA256=$h}
    } catch { return [PSCustomObject]@{Valid=$false;Detail=$_.Exception.Message;SHA256=''} }
}

function Get-RulePackStatus {
    $rows=@()
    $builtin=Join-Path $RulePackRoot 'BuiltIn_ComponentIdentityManifest.json'
    if(Test-Path -LiteralPath $builtin){
        try{$h=(Get-FileHash -Algorithm SHA256 -LiteralPath $builtin).Hash.ToLowerInvariant();$rows += [PSCustomObject]@{Name='BuiltIn_ComponentIdentityManifest';Kind='BUILTIN';Signature='ENGINE_PINNED';Trusted=$true;SHA256=$h;Signer='Engine embedded rules';Detail='内置规则由当前 EXE/Engine 生成；自动修复只接受内置已验证规则或未来明确配置的受信发布者规则包'}}catch{}
    }
    try{
        foreach($f in @(Get-ChildItem -LiteralPath $RulePackRoot -File -Filter '*.psd1' -ErrorAction SilentlyContinue)){
            $sig=$null;try{$sig=Get-AuthenticodeSignature -LiteralPath $f.FullName -ErrorAction Stop}catch{}
            $valid=($sig -and [string]$sig.Status -eq 'Valid')
            $thumb='';$signer='';if($sig -and $sig.SignerCertificate){$thumb=[string]$sig.SignerCertificate.Thumbprint;$signer=[string]$sig.SignerCertificate.Subject}
            $trusted=($valid -and $TrustedRulePackThumbprints.Count -gt 0 -and ($TrustedRulePackThumbprints -contains $thumb))
            $schema='';$parse='';try{$d=Import-PowerShellDataFile -LiteralPath $f.FullName -ErrorAction Stop;$schema=[string]$d.SchemaVersion;if(-not $schema){$parse='Missing SchemaVersion'}}catch{$parse=$_.Exception.Message}
            $h='';try{$h=(Get-FileHash -Algorithm SHA256 -LiteralPath $f.FullName).Hash.ToLowerInvariant()}catch{}
            $detail=if($trusted){'签名有效且发布者指纹属于 Engine 内置受信列表，可参与规则解析'}elseif($valid){'Authenticode 有效，但当前 Engine 没有配置该发布者指纹：仅审计，不授予自动修复权限'}else{'无有效 Authenticode：仅审计，不授予自动修复权限'}
            if($parse){$detail += '; parse='+$parse}
            $rows += [PSCustomObject]@{Name=$f.Name;Kind='EXTERNAL';Signature=$(if($valid){'VALID'}else{[string]$sig.Status});Trusted=$trusted;SHA256=$h;Signer=$signer;Detail=$detail;SchemaVersion=$schema}
        }
    }catch{}
    return $rows
}

function Test-PolicyPath([string]$Path,[string[]]$AllowedRoots) {
    if(-not $Path){return $false}
    try{$full=[IO.Path]::GetFullPath($Path).TrimEnd('\\')+'\\'}catch{return $false}
    foreach($r in @($AllowedRoots)){
        if(-not $r){continue};try{$root=[IO.Path]::GetFullPath([Environment]::ExpandEnvironmentVariables($r)).TrimEnd('\\')+'\\'}catch{continue}
        if($full.StartsWith($root,[StringComparison]::OrdinalIgnoreCase)){return $true}
    }
    return $false
}

function Invoke-PolicyOperation([hashtable]$Policy,[string]$Operation,[hashtable]$Args) {
    if(-not $Policy){throw 'Policy is required'}
    switch($Operation){
        'CreateDirectory' {
            $p=[string]$Args.Path;if(-not (Test-PolicyPath $p @($Policy.AllowedWriteRoots))){throw "Policy denied CreateDirectory: $p"};New-Item -ItemType Directory -Force -Path $p|Out-Null;return
        }
        'CopyFile' {
            $dst=[string]$Args.Destination;if(-not (Test-PolicyPath $dst @($Policy.AllowedWriteRoots))){throw "Policy denied CopyFile destination: $dst"};Copy-Item -LiteralPath ([string]$Args.Source) -Destination $dst -Force -ErrorAction Stop;return
        }
        'StopService' {
            $n=[string]$Args.Name;if(@($Policy.AllowedServices) -notcontains $n){throw "Policy denied StopService: $n"};Stop-Service -Name $n -Force -ErrorAction Stop;return
        }
        'StartService' {
            $n=[string]$Args.Name;if(@($Policy.AllowedServices) -notcontains $n){throw "Policy denied StartService: $n"};Start-Service -Name $n -ErrorAction Stop;return
        }
        default { throw "Unsupported policy operation: $Operation" }
    }
}

function Get-PnpProblemText([int]$Code){$m=@{0='设备正常';1='设备配置不正确';3='驱动可能损坏或系统资源不足';10='设备无法启动';12='没有足够的可用资源';14='需要重启计算机';18='需要重新安装驱动';19='注册表中的设备配置信息不完整或损坏';22='设备已被禁用';24='设备不存在/工作异常或驱动未完整安装';28='设备驱动未安装';31='Windows 无法加载此设备所需驱动';32='该设备的驱动服务已被禁用';37='Windows 无法初始化此设备驱动';39='驱动损坏或缺失';43='设备报告问题，Windows 已停止设备';45='设备当前未连接';48='驱动软件被阻止启动';52='Windows 无法验证驱动数字签名'};if($m.ContainsKey($Code)){return [string]$m[$Code]};return "ConfigManager ProblemCode=$Code"}
function Get-PnpRelatedInventory {
    $rows=@();$cim=@{};try{foreach($c in @(Get-CimInstance Win32_PnPEntity -ErrorAction SilentlyContinue)){if($c.PNPDeviceID){$cim[[string]$c.PNPDeviceID.ToUpperInvariant()]=$c}}}catch{}
    try{foreach($p in @(Get-PnpDevice -ErrorAction SilentlyContinue|Where-Object{$_.FriendlyName -match 'ASUS|ROG|ENE|NVIDIA|AMD|Display|VGA|High Definition Audio|ULTRAGEAR'})){$code=$null;try{$pr=Get-PnpDeviceProperty -InstanceId ([string]$p.InstanceId) -KeyName 'DEVPKEY_Device_ProblemCode' -ErrorAction Stop;if($null -ne $pr.Data){$code=[int]$pr.Data}}catch{};if($null -eq $code -and $cim.ContainsKey(([string]$p.InstanceId).ToUpperInvariant())){try{$code=[int]$cim[([string]$p.InstanceId).ToUpperInvariant()].ConfigManagerErrorCode}catch{}};if($null -eq $code){$code=if([string]$p.Status -eq 'OK'){0}else{-1}};$txt=if($code -ge 0){Get-PnpProblemText $code}else{'无法读取 ConfigManager ProblemCode'};$sev=if($code -eq 0 -and [string]$p.Status -eq 'OK'){'PASS'}elseif($code -in @(22,45) -and [string]$p.Class -in @('MEDIA','AudioEndpoint')){'INFO'}else{'WARN'};if([string]$p.FriendlyName -match '(?i)(NVIDIA|AMD).*(High Definition Audio|Display Audio)' -and $code -eq 22){$txt += '；如果不使用 HDMI/DisplayPort 显示器音频，主动禁用通常无需修复'};$rows += [PSCustomObject]@{Status=[string]$p.Status;Severity=$sev;Class=[string]$p.Class;FriendlyName=[string]$p.FriendlyName;InstanceId=[string]$p.InstanceId;ProblemCode=$code;ProblemText=$txt}}}catch{};return $rows
}
function Get-GPUHealthRows {
    $rows=@();try{foreach($g in @(Get-CimInstance Win32_VideoController -ErrorAction SilentlyContinue)){$st='PASS';if([string]$g.Status -and [string]$g.Status -ne 'OK'){$st='WARN'};$date='';try{$date=([Management.ManagementDateTimeConverter]::ToDateTime([string]$g.DriverDate)).ToString('yyyy-MM-dd')}catch{$date=[string]$g.DriverDate};$rows += [PSCustomObject]@{Category='GPU';Test=[string]$g.Name;Status=$st;Detail=("Driver={0}; DriverDate={1}; Status={2}; PNP={3}" -f $g.DriverVersion,$date,$g.Status,$g.PNPDeviceID)}}}catch{$rows += [PSCustomObject]@{Category='GPU';Test='Win32_VideoController';Status='WARN';Detail=$_.Exception.Message}};foreach($p in @(Get-PnpRelatedInventory|Where-Object{$_.Class -eq 'Display' -or $_.FriendlyName -match '(?i)(NVIDIA|AMD).*(High Definition Audio|Display Audio)'})){$rows += [PSCustomObject]@{Category=$(if($p.Class -eq 'Display'){'GPU PnP'}else{'Display Audio PnP'});Test=[string]$p.FriendlyName;Status=[string]$p.Severity;Detail=("Status={0}; ProblemCode={1} ({2}); InstanceId={3}" -f $p.Status,$p.ProblemCode,$p.ProblemText,$p.InstanceId)}};return $rows
}

function Get-GameCrashTelemetry([int]$Days=7,[int]$MaxEvents=120,[switch]$Raw) {
    $since=(Get-Date).AddDays(-1*$Days)
    $items=@()

    function Get-EventProcessName([object]$e) {
        $name=''
        try {
            if($e.Properties -and $e.Properties.Count -gt 0) {
                $candidate=[string]$e.Properties[0].Value
                if($candidate -match '(?i)\.exe$') { $name=$candidate }
            }
        } catch {}
        if(-not $name) {
            $msg=''
            try{$msg=[string]$e.Message}catch{}
            foreach($p in @(
                '(?im)(?:Faulting application name|Application Name|错误应用程序名称|故障应用程序名称)\s*[:：]\s*(?<v>[^,\r\n]+\.exe)',
                '(?im)(?:Hang application name|挂起应用程序名称)\s*[:：]\s*(?<v>[^,\r\n]+\.exe)'
            )){
                if($msg -match $p){$name=[string]$matches['v'];break}
            }
        }
        return $name.Trim()
    }

    function AddCrashEvent([object]$e,[string]$Category,[string]$Severity){
        if(-not $e){return}
        $msg=''
        try{$msg=[string]$e.Message}catch{}
        if($msg.Length -gt 700){$msg=$msg.Substring(0,700)}
        $proc=Get-EventProcessName $e
        $script:__crashItems += [PSCustomObject]@{
            Time=$e.TimeCreated
            Category=$Category
            Severity=$Severity
            Provider=[string]$e.ProviderName
            Id=[int]$e.Id
            Process=$proc
            Count=1
            Message=($msg -replace '[\r\n]+',' ')
        }
    }

    function Get-EventsBounded([hashtable]$Filter,[int]$Take) {
        try {
            return @(Get-WinEvent -FilterHashtable $Filter -MaxEvents $Take -ErrorAction Stop)
        } catch {
            try { return @(Get-WinEvent -FilterHashtable $Filter -ErrorAction SilentlyContinue | Select-Object -First $Take) }
            catch { return @() }
        }
    }

    $script:__crashItems=@()

    foreach($e in @(Get-EventsBounded @{LogName='Application';StartTime=$since;Id=1000} 50)){AddCrashEvent $e 'Application Crash' 'WARN'}
    foreach($e in @(Get-EventsBounded @{LogName='Application';StartTime=$since;Id=1002} 40)){AddCrashEvent $e 'Application Hang' 'WARN'}
    foreach($e in @(Get-EventsBounded @{LogName='Application';StartTime=$since;Id=1001} 60)){
        $m='';try{$m=[string]$e.Message}catch{}
        if($m -match '(?i)LiveKernelEvent|APPCRASH|BEX64|RADAR_PRE_LEAK'){AddCrashEvent $e 'Windows Error Reporting' 'WARN'}
    }
    foreach($e in @(Get-EventsBounded @{LogName='System';ProviderName='Display';StartTime=$since;Id=4101} 35)){AddCrashEvent $e 'GPU TDR / Display' 'WARN'}
    foreach($e in @(Get-EventsBounded @{LogName='System';ProviderName='Microsoft-Windows-WHEA-Logger';StartTime=$since} 45)){
        if($e.Id -in @(1,17,18,19,20,46,47)){AddCrashEvent $e 'WHEA Hardware' $(if($e.Id -in @(18,46)){'FAIL'}else{'WARN'})}
    }
    foreach($e in @(Get-EventsBounded @{LogName='System';ProviderName='Microsoft-Windows-Kernel-Power';StartTime=$since;Id=41} 25)){AddCrashEvent $e 'Unexpected Restart' 'WARN'}

    $items=@($script:__crashItems|Sort-Object Time -Descending)
    $script:__crashItems=$null

    if($Raw){
        return @($items|Select-Object -First $MaxEvents)
    }

    # UI view: collapse repeated identical app/provider events so one noisy service
    # does not occupy the entire page. Raw evidence is still exported separately.
    $grouped=@()
    foreach($g in @($items|Group-Object {
        $p=[string]$_.Process
        if(-not $p){$p='(unknown)'}
        "{0}|{1}|{2}|{3}" -f $_.Category,$_.Provider,$_.Id,$p
    })){
        $latest=@($g.Group|Sort-Object Time -Descending|Select-Object -First 1)[0]
        if(-not $latest){continue}
        $sev='WARN'
        if(@($g.Group|Where-Object{$_.Severity -eq 'FAIL'}).Count -gt 0){$sev='FAIL'}
        $grouped += [PSCustomObject]@{
            Time=$latest.Time
            Category=$latest.Category
            Severity=$sev
            Provider=$latest.Provider
            Id=$latest.Id
            Process=$latest.Process
            Count=$g.Count
            Message=$latest.Message
        }
    }
    return @($grouped|Sort-Object Time -Descending|Select-Object -First $MaxEvents)
}

function Get-CrashHealthRows([int]$Days=7) {
    $events=@(Get-GameCrashTelemetry $Days 180 -Raw);$rows=@()
    foreach($g in @($events|Group-Object Category)){
        $sev='PASS';if(@($g.Group|Where-Object{$_.Severity -eq 'FAIL'}).Count -gt 0){$sev='FAIL'}elseif($g.Count -gt 0){$sev='WARN'}
        $latest='';if($g.Group[0].Time){$latest=([datetime]$g.Group[0].Time).ToString('yyyy-MM-dd HH:mm:ss')}
        $rows += [PSCustomObject]@{Category='Crash';Test=[string]$g.Name;Status=$sev;Detail=("Last {0} days count={1}; latest={2}" -f $Days,$g.Count,$latest)}
    }
    if($rows.Count -eq 0){$rows += [PSCustomObject]@{Category='Crash';Test='Windows crash/event evidence';Status='PASS';Detail="最近 $Days 天未发现已监控的 Application Crash/Hang、LiveKernelEvent、Display 4101、WHEA 或 Kernel-Power 41 证据"}}
    return $rows
}

function Invoke-DllLoadTest([string]$Arch,[string[]]$Dlls) {
    $ps=Join-Path $env:WINDIR $(if($Arch -eq 'x86' -and [Environment]::Is64BitOperatingSystem){'SysWOW64\WindowsPowerShell\v1.0\powershell.exe'}else{'System32\WindowsPowerShell\v1.0\powershell.exe'})
    if(-not (Test-Path -LiteralPath $ps)){return [PSCustomObject]@{Success=$false;Detail='PowerShell arch host missing'}}
    $worker=Join-Path $DeepTestRoot ('dll_load_'+$Arch+'_'+[guid]::NewGuid().ToString('N')+'.ps1');$result=$worker+'.json'
    $list=($Dlls|ForEach-Object{"'"+($_ -replace "'","''")+"'"}) -join ','
    $code=@"
param([string]`$Result)
`$ErrorActionPreference='SilentlyContinue'
Add-Type -TypeDefinition @'
using System; using System.Runtime.InteropServices; public static class DllSmoke230 { [DllImport("kernel32.dll", CharSet=CharSet.Unicode, SetLastError=true)] public static extern IntPtr LoadLibraryW(string n); [DllImport("kernel32.dll")] public static extern bool FreeLibrary(IntPtr h); }
'@
`$out=@();foreach(`$n in @($list)){`$h=[DllSmoke230]::LoadLibraryW(`$n);`$ok=(`$h -ne [IntPtr]::Zero);if(`$ok){[DllSmoke230]::FreeLibrary(`$h)|Out-Null};`$out += [PSCustomObject]@{Dll=`$n;Loaded=`$ok}}
[PSCustomObject]@{Success=(@(`$out|Where-Object{-not `$_.Loaded}).Count -eq 0);Items=`$out}|ConvertTo-Json -Depth 5|Set-Content -LiteralPath `$Result -Encoding UTF8
"@
    try{$code|Set-Content -LiteralPath $worker -Encoding UTF8;$p=Start-Process -FilePath $ps -ArgumentList "-NoProfile -ExecutionPolicy Bypass -File `"$worker`" -Result `"$result`"" -PassThru -WindowStyle Hidden;$p.WaitForExit();if(Test-Path -LiteralPath $result){$o=Get-Content -LiteralPath $result -Raw|ConvertFrom-Json;return [PSCustomObject]@{Success=[bool]$o.Success;Detail=(@($o.Items|ForEach-Object{"$($_.Dll)=$($_.Loaded)"}) -join '; ')}}}catch{}finally{Remove-Item -LiteralPath $worker,$result -Force -ErrorAction SilentlyContinue}
    return [PSCustomObject]@{Success=$false;Detail='DLL load worker failed'}
}

function Get-AdditionalGameRuntimeRows {
    $rows=@()
    # .NET Framework 4.x
    try{$rel=(Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\NET Framework Setup\NDP\v4\Full' -Name Release -ErrorAction Stop).Release;$rows += [PSCustomObject]@{Category='.NET';Test='.NET Framework 4.x';Status='PASS';Detail="Release=$rel"}}catch{$rows += [PSCustomObject]@{Category='.NET';Test='.NET Framework 4.x';Status='INFO';Detail='未读取到 v4 Full Release；仅作为兼容信息，不自动安装'}}
    # Modern .NET Desktop runtimes
    $dotnetRows=@();foreach($root in @("$env:ProgramFiles\dotnet\shared\Microsoft.WindowsDesktop.App","${env:ProgramFiles(x86)}\dotnet\shared\Microsoft.WindowsDesktop.App")){if($root -and (Test-Path -LiteralPath $root)){try{$dotnetRows += Get-ChildItem -LiteralPath $root -Directory -ErrorAction SilentlyContinue|Select-Object -ExpandProperty Name}catch{}}}
    if($dotnetRows.Count -gt 0){$rows += [PSCustomObject]@{Category='.NET';Test='.NET Desktop Runtime';Status='PASS';Detail=('Installed: '+(@($dotnetRows|Sort-Object -Unique)-join ', '))}}else{$rows += [PSCustomObject]@{Category='.NET';Test='.NET Desktop Runtime';Status='INFO';Detail='未发现 Microsoft.WindowsDesktop.App；不是所有游戏都需要，因此不视为故障'}}
    # WebView2 runtime, discovered by product name rather than hard-coded GUID.
    $wv=@();foreach($root in @('HKLM:\SOFTWARE\Microsoft\EdgeUpdate\Clients\*','HKLM:\SOFTWARE\WOW6432Node\Microsoft\EdgeUpdate\Clients\*','HKCU:\SOFTWARE\Microsoft\EdgeUpdate\Clients\*')){try{$wv += Get-ItemProperty $root -ErrorAction SilentlyContinue|Where-Object{([string]$_.name -match '(?i)WebView2') -or ([string]$_.pv -and [string]$_.name -match '(?i)Microsoft Edge WebView')}}catch{}}
    if($wv.Count -gt 0){$rows += [PSCustomObject]@{Category='WebView2';Test='Microsoft Edge WebView2 Runtime';Status='PASS';Detail=('Versions: '+(@($wv|ForEach-Object{$_.pv}|Where-Object{$_}|Sort-Object -Unique)-join ', '))}}else{$rows += [PSCustomObject]@{Category='WebView2';Test='Microsoft Edge WebView2 Runtime';Status='INFO';Detail='未发现 WebView2；仅在游戏启动器明确依赖时才需要安装'}}
    # Vulkan/OpenAL loaders: absence alone is not a Windows fault.
    foreach($a in @('x64','x86')){
        $v=Invoke-DllLoadTest $a @('vulkan-1.dll');$rows += [PSCustomObject]@{Category='Vulkan';Test=("Vulkan loader $a");Status=$(if($v.Success){'PASS'}else{'INFO'});Detail=$v.Detail}
        $o=Invoke-DllLoadTest $a @('OpenAL32.dll');$rows += [PSCustomObject]@{Category='OpenAL';Test=("OpenAL loader $a");Status=$(if($o.Success){'PASS'}else{'INFO'});Detail=$o.Detail}
    }
    # XNA side-by-side inventory; missing is informational.
    $xna=@();foreach($root in @('HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*','HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*')){try{$xna += Get-ItemProperty $root -ErrorAction SilentlyContinue|Where-Object{$_.DisplayName -match '(?i)Microsoft XNA Framework'}}catch{}}
    $rows += [PSCustomObject]@{Category='XNA';Test='Microsoft XNA Framework';Status=$(if($xna.Count -gt 0){'PASS'}else{'INFO'});Detail=$(if($xna.Count -gt 0){(@($xna|ForEach-Object{"$($_.DisplayName) $($_.DisplayVersion)"}) -join '; ')}else{'未安装；只有明确依赖 XNA 的旧游戏才需要'})}
    return $rows
}

function Invoke-GamePlatformDeepTest {
    $rows=@();try{$rows += @(Invoke-GameRuntimeDeepTest)}catch{$rows += [PSCustomObject]@{Category='Runtime';Test='Existing deep test';Status='WARN';Detail=$_.Exception.Message}}
    $rows += @(Get-GPUHealthRows)
    $rows += @(Get-CrashHealthRows 7)
    $rows += @(Get-AdditionalGameRuntimeRows)
    $obj=[PSCustomObject]@{Version=$AppVersion;CheckedAt=(Get-Date).ToString('o');Rows=$rows};try{Write-JsonAtomic (Join-Path $DeepTestRoot 'LastGamePlatformDeepTest.json') $obj 12|Out-Null}catch{}
    return $rows
}

function Get-WerLocalDumpStatus([string]$ExeName='') {
    $root='HKLM:\SOFTWARE\Microsoft\Windows\Windows Error Reporting\LocalDumps';$out=@()
    try{
        if($ExeName){$paths=@(Join-Path $root $ExeName)}elseif(Test-Path -LiteralPath $root){$paths=@(Get-ChildItem -LiteralPath $root -ErrorAction SilentlyContinue|ForEach-Object{$_.PSPath})}else{$paths=@()}
        foreach($p in $paths){if(Test-Path -LiteralPath $p){$v=Get-ItemProperty -LiteralPath $p -ErrorAction SilentlyContinue;$out += [PSCustomObject]@{Exe=[IO.Path]::GetFileName([string]$p);DumpFolder=[Environment]::ExpandEnvironmentVariables([string]$v.DumpFolder);DumpCount=$v.DumpCount;DumpType=$v.DumpType}}}
    }catch{}
    return $out
}

function Set-WerLocalDumpConfiguration([string]$ExeName,[bool]$Enable) {
    if(-not (Get-AdminState)){throw 'WER LocalDumps configuration requires elevated broker'}
    if($ExeName -notmatch '^[A-Za-z0-9_.-]+\.exe$'){throw 'Invalid executable name'}
    $root='HKLM:\SOFTWARE\Microsoft\Windows\Windows Error Reporting\LocalDumps';$p=Join-Path $root $ExeName
    if($Enable){New-Item -Path $p -Force|Out-Null;New-ItemProperty -Path $p -Name DumpFolder -Value $CrashDumpRoot -PropertyType ExpandString -Force|Out-Null;New-ItemProperty -Path $p -Name DumpCount -Value 3 -PropertyType DWord -Force|Out-Null;New-ItemProperty -Path $p -Name DumpType -Value 2 -PropertyType DWord -Force|Out-Null;return "WER LocalDumps enabled for $ExeName; folder=$CrashDumpRoot; count=3; type=2(full)"}
    if(Test-Path -LiteralPath $p){Remove-Item -LiteralPath $p -Recurse -Force -ErrorAction Stop};return "WER LocalDumps disabled for $ExeName"
}

function Invoke-ASUSRepairHeadless([string]$Group) {
    if(-not (Get-AdminState)){throw 'Elevated broker required'}
    $snap=Get-SystemSnapshot -Force;$elig=Get-ASUSRepairEligibility $Group $snap;if(-not $elig.Eligible){throw ('Repair Eligibility BLOCK: '+(@($elig.Reasons)-join ' | '))}
    $plan=New-RepairPlan 'ASUS' $Group $snap;if(-not $plan.Eligible){throw ('Dry Run BLOCK: '+(@($plan.BlockingReasons)-join ' | '))}
    $tx=New-RepairTransaction $plan $snap;Set-TransactionState $tx 'SelfTestStarted' 'Elevated Broker: read-only SelfTest'
    $info=Get-ModuleInfo $Group;Save-RepairBaseline $Group $snap.Rows;$t=Get-Date;[void](Invoke-ModuleProcess $info.Module 'SelfTest');$st=Find-LatestSelfTestStatus $info.Pattern $t
    if(-not $st -or $st.Status -ne 'PASS'){Set-TransactionState $tx 'Failed' 'Broker SelfTest failed; destructive repair not started';return [PSCustomObject]@{Success=$false;TransactionId=$tx.TransactionId;State=$tx.State;Detail='SelfTest failed'}}
    Set-TransactionState $tx 'SelfTestPassed' ("Broker SelfTest PASS: "+$st.Dir);Set-TransactionState $tx 'RepairStarted' 'Elevated Broker authorized exact verified recipe';Set-TransactionState $tx 'ModuleExecuting' 'Legacy verified module adapter executing under hash/identity/policy eligibility gates'
    $script:RepairExecutionActive=$true;try{[void](Invoke-ModuleProcess $info.Module 'Start')}finally{$script:RepairExecutionActive=$false}
    $pending=Get-PendingRepair
    if($pending){Set-TransactionState $tx 'AwaitingReboot' 'Stage 1 completed; real reboot required'}else{$fx=Find-LatestFixStatus $info.Pattern $t;if($fx -and $fx.Status -eq 'SUCCESS'){Set-TransactionState $tx 'SuccessPendingVerification' ("Module SUCCESS: "+$fx.Dir)}elseif($fx -and $fx.Status -match '^FAILED'){Set-TransactionState $tx 'NeedsAttention' ("Module status "+$fx.Status)}else{Set-TransactionState $tx 'NeedsVerification' 'Module returned; strict verification required'}}
    return [PSCustomObject]@{Success=$true;TransactionId=$tx.TransactionId;State=$tx.State;Detail=$tx.LastDetail}
}

function Invoke-RuntimeRepairHeadless {
    if(-not (Get-AdminState)){throw 'Elevated broker required'}
    $script:SnapshotCacheTime=[datetime]::MinValue
    $snap=Get-SystemSnapshot -Force
    $elig=Get-RuntimeRepairEligibility $snap
    if(-not $elig.Eligible){throw ('现在不能自动修运行库：'+(@($elig.Reasons)-join '；'))}
    $plan=New-RepairPlan 'RUNTIME' '' $snap
    if(-not $plan.Eligible){throw ('现在不能自动修运行库：'+(@($plan.BlockingReasons)-join '；'))}
    $tx=New-RepairTransaction $plan $snap
    Set-TransactionState $tx 'RepairStarted' '开始修复运行库'
    $script:RepairExecutionActive=$true
    try{$r=Invoke-RuntimeAutoRepair}finally{$script:RepairExecutionActive=$false}
    $detail=(@($r.Messages)|ForEach-Object{ConvertTo-CustomerSentence ([string]$_)} | Where-Object {$_}) -join ' '
    if(-not $detail){$detail=if($r.Success){'运行库已修好。'}else{'运行库没有完全修好。'}}
    if($r.Success){Set-TransactionState $tx 'SuccessPendingVerification' $detail}else{Set-TransactionState $tx 'NeedsAttention' $detail}
    return [PSCustomObject]@{Success=[bool]$r.Success;TransactionId=$tx.TransactionId;State=$tx.State;Detail=$detail}
}

function Invoke-ContinuePendingRepairHeadless {
    if(-not (Get-AdminState)){throw 'Elevated broker required'}
    $p=Get-PendingRepair;$tx=Sync-OpenTransactionState;if(-not $p){return [PSCustomObject]@{Success=$false;Detail='No PostReboot pending repair';State=$(if($tx){$tx.State}else{'NONE'})}}
    if($tx -and $tx.State -eq 'AwaitingReboot' -and $tx.BootTimeBefore){$boot=Get-BootTimeText;if($boot -and [string]$boot -eq [string]$tx.BootTimeBefore){throw 'Real reboot gate BLOCK: BootTime unchanged'}}
    if($tx){Set-TransactionState $tx 'PostRebootStarted' 'Elevated Broker invoking PostReboot'};$script:RepairExecutionActive=$true;try{[void](Invoke-ModuleProcess $p.Module 'PostReboot')}finally{$script:RepairExecutionActive=$false}
    if($tx){$info=Get-ModuleInfo ([string]$tx.Group);$st=[datetime]::MinValue;try{$st=[datetime]$tx.StartedAt}catch{};$fx=Find-LatestFixStatus $info.Pattern $st;if($fx -and $fx.Status -eq 'SUCCESS'){Set-TransactionState $tx 'SuccessPendingVerification' ("PostReboot SUCCESS: "+$fx.Dir)}elseif($fx -and $fx.Status -match '^FAILED'){Set-TransactionState $tx 'NeedsAttention' ("PostReboot "+$fx.Status)}else{Set-TransactionState $tx 'NeedsVerification' 'PostReboot returned; strict verification required'}}
    return [PSCustomObject]@{Success=$true;Detail='PostReboot invoked';State=$(if($tx){$tx.State}else{'UNKNOWN'});TransactionId=$(if($tx){$tx.TransactionId}else{''})}
}

function Start-ElevatedBroker([string]$Action,[string]$Group='',[string]$ExeName='') {
    if($script:BrokerProcess){try{if(-not $script:BrokerProcess.HasExited){[System.Windows.Forms.MessageBox]::Show('Elevated Repair Broker 正在执行另一项操作。')|Out-Null;return $false}}catch{}}
    $bi=Test-BrokerIntegrity;if(-not $bi.Valid){[System.Windows.Forms.MessageBox]::Show("Broker 完整性校验失败，拒绝提权执行。`r`n$($bi.Detail)",'安全阻断',[System.Windows.Forms.MessageBoxButtons]::OK,[System.Windows.Forms.MessageBoxIcon]::Error)|Out-Null;return $false}
    $id='BR-'+(Get-Date -Format 'yyyyMMdd-HHmmss')+'-'+([guid]::NewGuid().ToString('N').Substring(0,8));$req=Join-Path $BrokerRequestRoot ($id+'.request.json');$resp=Join-Path $BrokerRequestRoot ($id+'.response.json')
    $obj=[PSCustomObject]@{SchemaVersion=2;RequestId=$id;CreatedAt=(Get-Date).ToString('o');Action=$Action;Group=$Group;ExeName=$ExeName;ResponsePath=$resp;EngineVersion=$AppVersion;BuildId=$BuildId;EngineSHA256=$script:EngineSHA256;BuildInfoSHA256=$script:BuildInfoSHA256}
    if(-not (Write-JsonAtomic $req $obj 8)){return $false}
    $ps=Join-Path $env:WINDIR 'System32\WindowsPowerShell\v1.0\powershell.exe';$arg="-NoProfile -ExecutionPolicy Bypass -File `"$BrokerPath`" -RequestPath `"$req`" -EnginePath `"$PSCommandPath`""
    try{$p=Start-Process -FilePath $ps -Verb RunAs -ArgumentList $arg -PassThru -ErrorAction Stop;$script:BrokerProcess=$p;$script:BrokerRequestPath=$req;$script:BrokerResponsePath=$resp;$script:BrokerOperationLabel=$Action;$script:BrokerStartedAt=Get-Date;return $true}catch{[System.Windows.Forms.MessageBox]::Show("未启动 Elevated Broker：$($_.Exception.Message)",'UAC / Broker',[System.Windows.Forms.MessageBoxButtons]::OK,[System.Windows.Forms.MessageBoxIcon]::Warning)|Out-Null;return $false}
}

function Import-BrokerResponse {
    if(-not $script:BrokerResponsePath -or -not (Test-Path -LiteralPath $script:BrokerResponsePath)){return $null}
    try{return (Get-Content -LiteralPath $script:BrokerResponsePath -Raw|ConvertFrom-Json)}catch{return $null}
}

function Get-ArchitectureSecuritySummary {
    $bi=Test-BrokerIntegrity;$rp=@(Get-RulePackStatus);$trustedExternal=@($rp|Where-Object{$_.Kind -eq 'EXTERNAL' -and $_.Trusted}).Count
    $bc=Get-BuildConsistency;return [PSCustomObject]@{GuiElevation=(Get-AdminState);BrokerValid=$bi.Valid;BrokerSHA256=$bi.SHA256;BuildConsistency=$bc.Status;EngineVersion=$AppVersion;BuildId=$BuildId;EngineSHA256=$script:EngineSHA256;RulePacks=$rp.Count;TrustedExternalRulePacks=$trustedExternal;PolicyMode='Central eligibility + policy gate; legacy ASUS recipes run only through hash-locked adapter';ExternalRuleAutoRepairEnabled=($trustedExternal -gt 0)}
}

if($LibraryMode){return}

throw 'RepairCenter.ps1 is backend-only in the WinUI 3 build. Launch WindowsGameRuntimeASUSSelfHealing.WinUI.exe instead.'
